return doc
]],
["mfg/hmi/hal/display_real.lua"] = [[










local backend = {}

backend.name = "real"



local PALETTE = {
text = colours.white,
title = colours.white,
label = colours.lightGrey,
dim = colours.grey,
good = colours.lime,
warn = colours.yellow,
bad = colours.red,
stale = colours.grey,
action = colours.lightBlue,
selected = colours.white,
flow = colours.grey,
}

local target = nil
local isMonitor = false
local painted = nil

local SCALE = 0.5





local function forget()
target, isMonitor, painted = nil, false, nil
end

local function resolve()
if target then return target end

for _, name in ipairs(peripheral.getNames()) do
if peripheral.getType(name) == "monitor" then
target = peripheral.wrap(name)
isMonitor = true



if target.setTextScale then pcall(target.setTextScale, SCALE) end
return target
end
end

target = term.current()
isMonitor = false
return target
end

function backend.attached()
resolve()
return isMonitor and "monitor" or "terminal"
end

function backend.size()
local screen = resolve()


if isMonitor and screen.getTextScale then
local ok, scale = pcall(screen.getTextScale)
if ok and scale ~= SCALE then
pcall(screen.setTextScale, SCALE)
painted = nil
end
end
local width, height = screen.getSize()
return width, height
end




















local function cellsOf(grid)
local cells = {}
for y = 1, grid.height do
local row = {}
for _, run in ipairs(grid.rows[y] or {}) do
for i = 1, #run.text do
row[run.x + i - 1] = {char = run.text:sub(i, i),
colour = run.colour}
end
end
cells[y] = row
end
return cells
end

function backend.paint(grid)
local screen = resolve()
local colour = screen.isColour and screen.isColour() or false
local width, height = screen.getSize()

local cells = cellsOf(grid)



if not painted or painted.width ~= width or painted.height ~= height then
screen.setBackgroundColour(colours.black)
screen.clear()
painted = {width = width, height = height, cells = {}}
end

for y = 1, math.min(grid.height, height) do
local now = cells[y] or {}
local before = painted.cells[y] or {}
local x = 1
while x <= width do
local a, b = now[x], before[x]
local same = (a == nil and b == nil)
or (a and b and a.char == b.char and a.colour == b.colour)
if same then
x = x + 1
else


local from = x
local text, runColour = {}, (a and a.colour) or "text"
while x <= width do
local m, n = now[x], before[x]
local matched = (m == nil and n == nil)
or (m and n and m.char == n.char and m.colour == n.colour)
if matched then break end
if m and m.colour ~= runColour then break end
text[#text + 1] = m and m.char or " "
x = x + 1
end
if #text > 0 then
screen.setTextColour(colour
and (PALETTE[runColour] or colours.white) or colours.white)
screen.setCursorPos(from, y)
screen.write(table.concat(text))
end
end
end
painted.cells[y] = now
end

screen.setTextColour(colours.white)
end






function backend.invalidate()
painted = nil
end











function backend.touchable()
local screen = resolve()
if isMonitor then
return screen.isColour and screen.isColour() or false
end
return term.isColour and term.isColour() or false
end


function backend.colour()
local screen = resolve()
return screen.isColour and screen.isColour() or false
end






function backend.input(seconds)
local timer = os.startTimer(seconds or 2)
while true do
local event, a, b, c = os.pullEvent()

if event == "timer" and a == timer then
return nil
elseif event == "monitor_touch" then
return {kind = "touch", x = b, y = c}
elseif event == "mouse_click" and not isMonitor then


return {kind = "touch", x = b, y = c}
elseif event == "key" then
return {kind = "key", key = a}
elseif event == "char" then
return {kind = "char", char = a}
elseif event == "monitor_resize" or event == "peripheral"
or event == "peripheral_detach" then


forget()
return nil
end
end
end

return backend
]],
["mfg/hmi/host.lua"] = [[















local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")
local panes = require("mfg.hmi.panes")
local app = require("mfg.hmi.app")
local panel = require("mfg.hmi.panel")
local order = require("mfg.hmi.orderpanel")
local storage = require("mfg.hmi.storagepanel")

local APPS = {
{name = "order", label = "Order"},
{name = "register", label = "Register"},
{name = "batch", label = "Batch"},
{name = "storage", label = "Storage"},
}

local host = {}



function host.new(opts)
opts = opts or {}
local shared = {host = opts.host, display = opts.display,
transport = opts.transport, now = opts.now, source = opts.source}
local function with(extra)
local out = {}
for k, v in pairs(shared) do out[k] = v end
for k, v in pairs(extra) do out[k] = v end
return out
end

local screen = panes.new({title = "MFG"})
screen.display = opts.display
screen.views = {
order = order.new(shared),
register = panel.new(with({action = "register_recipe", verb = "Register",
title = "REGISTER",
note = "Crafts one set to learn what it makes. The product stays in the "
.. "pool."})),
batch = panel.new(with({action = "run_batch", verb = "Run", title = "BATCH"})),
storage = storage.new(shared),
}
screen.modules = {order = order, register = panel, batch = panel, storage = storage}

for index, entry in ipairs(APPS) do
local name = entry.name
local view, module = screen.views[name], screen.modules[name]
panes.add(screen, {
name = name,
label = entry.label,
key = tostring(index),
render = function(width, height) return module.document(view, width, height) end,
handle = function(action) return module.act(view, action) end,
ready = function() return view.offer ~= nil end,
})
end
return screen
end

function host.view(screen, name)
return screen.views[name or screen.current]
end



local function chosen(screen)
local module = screen.modules[screen.current]
if module.refresh then module.refresh(screen.views[screen.current]) end
end

function host.select(screen, name)
local ok, why = panes.select(screen, name)
if ok then chosen(screen) end
return ok, why
end




function host.render(screen)
local display = screen.display
local width, height = display.size()
local opts = {keys = not display.touchable(), colour = display.colour()}

local grid, report = panes.render(screen, width, height, opts)
local view, module = host.view(screen), screen.modules[screen.current]
if grid and module.settle and module.settle(view, report) then
grid, report = panes.render(screen, width, height, opts)
end

if not grid then
local diagnostic = doc.text("screen too small: " .. doc.explain(report),
{colour = "bad", wrap = true, keep = doc.REQUIRED, name = "diagnostic"})
grid = doc.render(diagnostic, width, height, opts)
end
screen.lastReport = report
if grid then display.paint(grid) end
return grid
end











function host.handle(screen, event, grid)
if not event then return false end
local isLeader = event.kind == "key" and keys and event.key == keys[panes.LEADER]
local module = screen.modules[screen.current]
local list = module.searching and module.searching(host.view(screen))
if list and not isLeader and not screen.leaderPending and app.type(list, event) then
return true
end
if not isLeader and not input.heard(event) then
return false
end
local before = screen.current
local outcome = panes.handle(screen, event, grid)
if screen.current ~= before then chosen(screen) end
return outcome
end





function host.pass(screen)
local names = {screen.current}
for _, name in ipairs(screen.order) do
if name ~= screen.current then names[#names + 1] = name end
end
for _, name in ipairs(names) do
local view, module = screen.views[name], screen.modules[name]
local job = module.nextJob(view)
if job then
module.exchange(view, job)
return true
end
end
return false
end

function host.serve(screen, opts)
opts = opts or {}
while true do
if not host.pass(screen) then sleep(opts.idle or 0.2) end
end
end

function host.run(screen, opts)
opts = opts or {}
parallel.waitForAny(
function() host.serve(screen, opts) end,
function()
input.drive(screen.display,
function() return host.render(screen) end,
function(event, grid) return host.handle(screen, event, grid) end,
{wait = opts.wait or 1})
end)
end

return host
]],
["mfg/hmi/input.lua"] = [[





















local doc = require("mfg.hmi.doc")

local input = {}












function input.normalise(event, a, b, c)
if type(event) == "table" then return event end

if event == "monitor_touch" then
return {kind = "touch", x = b, y = c, side = a}
elseif event == "mouse_click" then
return {kind = "touch", x = b, y = c, button = a}
elseif event == "key" then
return {kind = "key", key = a}
elseif event == "char" then
return {kind = "char", char = a}
end
return nil
end




function input.keys(grid)
if not grid then return {} end
return grid.keys or {}
end







function input.scoped(leader, key)
if not leader then return tostring(key) end
return ("%s %s"):format(tostring(leader), tostring(key))
end



local DIGITS = {
one = "1", two = "2", three = "3", four = "4", five = "5",
six = "6", seven = "7", eight = "8", nine = "9", zero = "0",

numPadEnter = "enter",
}


function input.keyName(event)
if not event then return nil end
if event.kind == "char" then return event.char end
if event.kind == "key" and event.key and keys then
local name = keys.getName and keys.getName(event.key)
if not name then return nil end
return DIGITS[name] or name
end
return nil
end






input.NAMED = {
enter = true, backspace = true, delete = true, left = true, right = true,
up = true, down = true, pageUp = true, pageDown = true, home = true,
["end"] = true,
}



function input.heard(event)
if not event then return false end
if event.kind ~= "key" then return true end
return input.NAMED[input.keyName(event)] == true
end







function input.actionFor(grid, event, opts)
if not grid or not event then return nil end
opts = opts or {}

if event.kind == "touch" then
if not event.x or not event.y then return nil end
return doc.hit(grid, event.x, event.y)
end

local name = input.keyName(event)
if not name then return nil end





if opts.leader then
return input.keys(grid)[input.scoped(opts.leader, name)]
end

return input.keys(grid)[name]
end











function input.drive(display, render, handle, opts)
opts = opts or {}
local wait = opts.wait or 1

while true do
local grid = render and render() or nil
local event = display.input(wait)
if event then
local outcome = handle(event, grid)
if outcome == "quit" then return "quit" end
end
end
end

return input
]],
["mfg/hmi/orderpanel.lua"] = [[













local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")
local app = require("mfg.hmi.app")
local validate = require("mfg.common.actions.validate")

local order = {}

order.ACTION = "make"

order.OFFER_RETRY = 5
order.OFFER_REFRESH = 30
order.JOBS_EVERY = 5




order.READ = {timeout = 3, attempts = 2}
order.MAKE = {timeout = 10, attempts = 1}



function order.new(opts)
opts = opts or {}
return {
host = opts.host or "mfg",
display = opts.display,
transport = opts.transport,
now = opts.now,

offer = nil,
offerWhy = nil,
offerAskedAt = nil,
recipes = {},
recipe = nil,
quantity = 1,
list = app.newList(),

confirming = nil,
sending = nil,
result = nil,

jobs = nil,
jobsWhy = nil,
jobsAt = nil,

link = {state = "unknown"},
queue = {},
}
end

order.parameter = app.parameter

local function clampQuantity(view, value)
local param = app.parameter(view, "quantity")
return app.clamp(value, param and param.min or 1, param and param.max or 4096)
end

local function labelOf(view, id)
for _, entry in ipairs(view.recipes) do
if entry.value == id then return entry.label end
end
return tostring(id)
end


function order.params(view)
if not view.offer then return nil, "the controller has not said what it offers" end
if #view.recipes == 0 then return nil, "no recipes yet -- register one" end
if not view.recipe then return nil, "pick a recipe" end
local checked, why = validate.check(view.offer,
{recipe = view.recipe, quantity = view.quantity})
if not checked then return nil, why end
return checked
end

function order.blocked(view)
if view.sending then return "an order is being sent" end
local _, why = order.params(view)
return why
end



function order.offerDue(view)
if not view.offerAskedAt then return true end
local every = view.offer and order.OFFER_REFRESH or order.OFFER_RETRY
return (app.clock(view) - view.offerAskedAt) >= every * 1000
end

function order.jobsDue(view)
if not view.offer then return false end
if not view.jobsAt then return true end
return (app.clock(view) - view.jobsAt) >= order.JOBS_EVERY * 1000
end



function order.refresh(view)
view.offerAskedAt = nil
view.jobsAt = nil
end

function order.nextJob(view)
local job = table.remove(view.queue, 1)
if job then return job end
if order.offerDue(view) then return {kind = "offer"} end
if order.jobsDue(view) then return {kind = "jobs"} end
return nil
end



local function recipeRows(view)
if #view.recipes == 0 then
return {doc.text("no recipes yet -- register one in the Register app",
{colour = "warn", wrap = true, keep = 20, name = "no-recipes"})}
end
local entries = {}
for _, entry in ipairs(view.recipes) do
entries[#entries + 1] = {value = entry.value, label = entry.label or entry.value,
selected = view.recipe == entry.value}
end
return app.listRows(view.list, entries, "recipe",
function(entry) return {kind = "recipe", recipe = entry.value} end)
end

local function actionRow(view)
local blocked = order.blocked(view)
return doc.row({
doc.button("Make", {key = (not blocked) and "enter" or nil,
colour = blocked and "dim" or "good",
action = (not blocked) and {kind = "make"} or nil,
keep = doc.REQUIRED, name = "make"}),
doc.gap(1),
doc.text(blocked or "", {colour = "dim", truncate = doc.TRUNCATED, keep = 4,
name = "why-blocked"}),
}, {keep = doc.REQUIRED, name = "actions"})
end

local function confirmRows(view)
local question
if view.confirming.cancel then
question = ("Cancel job %d?"):format(view.confirming.cancel)
else
local params = view.confirming.make
question = ("Make %d of %s?"):format(params.quantity, labelOf(view, params.recipe))
end
local note = view.confirming.cancel
and "A batch already running finishes first; nothing after it runs."
or "Queues a job. The controller crafts it, and the ingredients it makes too."
return {
doc.text(question, {colour = "title", wrap = true, keep = doc.REQUIRED,
name = "confirm"}),
doc.text(note, {colour = "text", wrap = true, keep = 6, name = "note"}),
doc.row({
doc.button("yes", {key = "y", colour = "good", action = {kind = "yes"},
keep = doc.REQUIRED, name = "yes"}),
doc.gap(1),
doc.button("no", {key = "n", colour = "bad", action = {kind = "no"},
keep = doc.REQUIRED, name = "no"}),
}, {keep = doc.REQUIRED, name = "confirm-actions"}),
}
end


local function statusRow(view)
if view.sending then
local seconds = math.floor((app.clock(view) - view.sending.since) / 1000)
return doc.text(("ordering %d of %s.. %ds"):format(view.sending.params.quantity,
labelOf(view, view.sending.params.recipe), seconds),
{colour = "warn", wrap = true, keep = 8, name = "status"})
end
local result = view.result
if not result then return doc.text("", {colour = "dim", keep = 1, name = "status"}) end

local fields = result.fields or {}
if result.status == app.COMPLETED and result.kind == "make" then
local steps = {}
for _, step in ipairs(fields.steps or {}) do
steps[#steps + 1] = ("%s x%d"):format(tostring(step.label), step.sets)
end
return doc.text(("job %d queued: %d sets -> %d %s (%s)"):format(
fields.job or 0, fields.sets or 0, fields.yield or 0,
app.shortName(fields.product), table.concat(steps, ", ")),
{colour = "good", wrap = true, keep = 8, name = "status"})
elseif result.status == app.COMPLETED then
return doc.text(("job %d cancelled"):format(result.job or 0),
{colour = "good", wrap = true, keep = 8, name = "status"})
elseif result.status == app.TIMED_OUT then
return doc.text(("no answer from %s -- it may or may not have been queued; "
.. "the jobs below will say"):format(view.host),
{colour = "warn", wrap = true, keep = 8, name = "status"})
end
return doc.text("refused: " .. tostring(result.reason),
{colour = "bad", wrap = true, keep = 8, name = "status"})
end


local function describeJob(job)
local state = tostring(job.state)
if job.state == "blocked" then
return ("blocked: %s"):format(tostring(job.reason))
elseif job.state == "queued" or job.state == "running" then
local step = job.step
return ("%s step %d/%d%s"):format(state, job.position or 1, job.steps or 1,
step and (" %s %d/%d"):format(tostring(step.label), step.done or 0,
step.sets or 0) or "")
end
return state
end

local OPEN = {queued = true, running = true, blocked = true}

local function jobRows(view)
local rows = {}
if view.jobsWhy and not view.jobs then
rows[#rows + 1] = doc.text("jobs: " .. view.jobsWhy, {colour = "bad",
truncate = doc.TRUNCATED, keep = 2, name = "jobs-why"})
return rows
end
if not view.jobs or #view.jobs == 0 then return rows end

rows[#rows + 1] = doc.rule({keep = 3})
local shown = 0
for index = #view.jobs, 1, -1 do
local job = view.jobs[index]
shown = shown + 1
local children = {
doc.text(("#%d %s %s"):format(job.id, tostring(job.label or
app.shortName(job.product)), describeJob(job)),
{width = "fill", truncate = doc.TRUNCATED,
colour = job.state == "blocked" and "warn"
or (OPEN[job.state] and "text" or "dim"),
name = "job:" .. job.id}),
}
if OPEN[job.state] then
children[#children + 1] = doc.gap(1)
children[#children + 1] = doc.button("x", {colour = "bad",
action = {kind = "cancel", job = job.id}, name = "cancel:" .. job.id})
end

rows[#rows + 1] = doc.row(children, {keep = math.max(1, 3 - shown),
name = "jobrow:" .. job.id})
end
return rows
end

function order.document(view, width, height)
local rows = {app.header(view, "ORDER"), doc.rule({keep = 2})}

if not view.offer then
rows[#rows + 1] = doc.text(view.offerWhy
and ("the controller refused: " .. tostring(view.offerWhy))
or "asking the controller what it offers..",
{colour = view.offerWhy and "bad" or "dim", wrap = true,
keep = doc.REQUIRED, name = "offer-state"})
elseif view.confirming then
for _, row in ipairs(confirmRows(view)) do rows[#rows + 1] = row end
else
for _, row in ipairs(recipeRows(view)) do rows[#rows + 1] = row end
rows[#rows + 1] = app.quantityRow(view.quantity, not view.sending)
rows[#rows + 1] = actionRow(view)
end

rows[#rows + 1] = statusRow(view)
for _, row in ipairs(jobRows(view)) do rows[#rows + 1] = row end
rows[#rows + 1] = doc.spacer()
return doc.stack(rows, {name = "order"})
end

function order.settle(view, report)
return app.settle(view.list, report, "recipe")
end



function order.act(view, action)
local kind = action and action.kind

if app.page(view.list, kind) then return true end
if kind == "recipe" then
view.recipe = action.recipe
return true
elseif kind == "delta" then
view.quantity = clampQuantity(view, view.quantity + (action.n or 0))
return true
elseif kind == "make" then
local params, why = order.params(view)
if not params then
view.result = {status = app.REJECTED, reason = why}
return true
end
view.confirming = {make = params}
return true
elseif kind == "cancel" then
view.confirming = {cancel = action.job}
return true
elseif kind == "yes" then
local confirmed = view.confirming
view.confirming = nil
if confirmed and confirmed.make then
app.ask(view, {kind = "make", params = confirmed.make})
elseif confirmed and confirmed.cancel then
app.ask(view, {kind = "cancel", job = confirmed.cancel})
end
return true
elseif kind == "no" then
view.confirming = nil
return true
end
return false
end


function order.searching(view)
if view.offer and not view.confirming and #view.recipes > 0 then return view.list end
return nil
end


function order.handle(view, event, grid)
if order.searching(view) and app.type(view.list, event) then return true end
if not input.heard(event) then return false end
local action = input.actionFor(grid, event)
if not action then return false end
return order.act(view, action)
end



function order.exchange(view, job)
local body, opts
if job.kind == "offer" then
view.offerAskedAt = app.clock(view)
body, opts = {command = "offer", name = order.ACTION}, order.READ
elseif job.kind == "jobs" then
view.jobsAt = app.clock(view)
body, opts = {command = "jobs"}, order.READ
elseif job.kind == "make" then
body = {command = "make", recipe = job.params.recipe,
quantity = job.params.quantity}
opts = order.MAKE
view.sending = {params = job.params, since = app.clock(view)}
view.result = nil
elseif job.kind == "cancel" then
body, opts = {command = "cancel_job", job = job.job}, order.MAKE
else
return false
end

local answer = view.transport.request(body, opts) or {}
order.apply(view, job, answer)
return true
end

function order.apply(view, job, answer)
app.noteLink(view, answer)

if job.kind == "offer" then
local decl = answer.status == app.COMPLETED
and type(answer.actions) == "table" and answer.actions[1]
if not decl then


if not view.offer then
view.offerWhy = answer.reason or answer.status or "no answer"
end
return
end
view.offer, view.offerWhy = decl, nil

view.recipes = {}
local param = app.parameter(view, "recipe")
if param and type(param.choices) == "table" and not param.choices.source then
for _, entry in ipairs(param.choices) do
if type(entry) == "table" then
view.recipes[#view.recipes + 1] = {value = entry.value,
label = entry.label or entry.value}
else
view.recipes[#view.recipes + 1] = {value = entry, label = entry}
end
end
end
local still = false
for _, entry in ipairs(view.recipes) do
if entry.value == view.recipe then still = true end
end
if not still then view.recipe = nil end
if not view.recipe and #view.recipes == 1 then
view.recipe = view.recipes[1].value
end
view.quantity = clampQuantity(view, view.quantity)

elseif job.kind == "jobs" then
if answer.status == app.COMPLETED and type(answer.jobs) == "table" then
view.jobs, view.jobsWhy = answer.jobs, nil
else
view.jobsWhy = tostring(answer.reason or answer.status or "no answer")
end

elseif job.kind == "make" or job.kind == "cancel" then
view.sending = nil
view.result = {kind = job.kind, status = answer.status or app.REJECTED,
reason = answer.reason, fields = answer, job = job.job,
at = app.clock(view)}

view.jobsAt = nil
end
end

return order
]],
["mfg/hmi/panel.lua"] = [[
































local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")
local app = require("mfg.hmi.app")
local pattern = require("mfg.common.pattern")
local validate = require("mfg.common.actions.validate")

local panel = {}



panel.ACTION = "run_batch"



panel.COMPLETED = "completed"
panel.REJECTED = "rejected"
panel.TIMED_OUT = "timed_out"



panel.OFFER_RETRY = 5






panel.READ = {timeout = 3, attempts = 2}
panel.RUN = {timeout = 60, attempts = 1}



function panel.new(opts)
opts = opts or {}
return {


action = opts.action or panel.ACTION,
verb = opts.verb or "Run",
title = opts.title or "CRAFT",
note = opts.note,

host = opts.host or "mfg",




source = opts.source or require("mfg.common.config").setting("source"),
display = opts.display,
transport = opts.transport,
now = opts.now,

offer = nil,
offerWhy = nil,
offerAskedAt = nil,
nodes = {},
target = nil,

stock = nil,
stockWhy = nil,

cells = {},
amount = 1,
output = nil,


picking = nil,
pickList = app.newList(),

confirming = nil,
running = nil,
result = nil,




link = {state = "unknown"},

queue = {},
}
end

local function clock(view)
if view.now then return view.now() end
return os.epoch("utc")
end



function panel.parameter(view, name)
if not view.offer then return nil end
for _, param in ipairs(view.offer.parameters or {}) do
if param.name == name then return param end
end
return nil
end


function panel.amountRange(view)
local param = panel.parameter(view, "amount")
if not param then return nil end
return param.min or 1, param.max or param.min or 1
end

local function clampAmount(view, value)
local min, max = panel.amountRange(view)
if not min then return value end
value = math.floor(tonumber(value) or min)
if value < min then value = min end
if value > max then value = max end
return value
end





function panel.slotOf(cell)
return pattern.GRID[cell]
end

function panel.pattern(view)
local out, any = {}, false
for cell = 1, 9 do
local item = view.cells[cell]
if item then
out[panel.slotOf(cell)] = item
any = true
end
end
if not any then return nil end
return out
end

local function sortedSlots(slots)
local out = {}
for slot in pairs(slots) do out[#out + 1] = slot end
table.sort(out)
return out
end



local function shortName(item)
if type(item) ~= "string" then return "" end
return item:match("[^:]+$") or item
end





function panel.params(view)
if not view.offer then
return nil, "the controller has not said what it offers"
end
if not view.target then return nil, "pick a node" end
local slots = panel.pattern(view)
if not slots then return nil, "the grid is empty" end




local params = {target = view.target, pattern = slots}
if panel.parameter(view, "pattern_id") then params.pattern_id = pattern.id(slots) end
if panel.parameter(view, "amount") then params.amount = view.amount end
if panel.parameter(view, "source") then params.source = view.source end
if panel.parameter(view, "output") and view.output then params.output = view.output end
local checked, why = validate.check(view.offer, params)
if not checked then return nil, why end
return checked
end


function panel.blocked(view)
if view.running then return "a batch is running" end
local _, why = panel.params(view)
return why
end





function panel.ask(view, job)
for _, queued in ipairs(view.queue) do
if queued.kind == job.kind then return false end
end
view.queue[#view.queue + 1] = job
return true
end

function panel.offerDue(view)
if view.offer then return false end
if not view.offerAskedAt then return true end
return (clock(view) - view.offerAskedAt) >= panel.OFFER_RETRY * 1000
end



local function linkElement(view)
local link = view.link
if link.state == "ok" then
return doc.text(view.host .. " ok", {colour = "good", keep = doc.REQUIRED,
truncate = doc.TRUNCATED, name = "link"})
elseif link.state == "down" then
return doc.text(("%s down: %s"):format(view.host, tostring(link.reason)),
{colour = "bad", keep = doc.REQUIRED, truncate = doc.TRUNCATED,
name = "link"})
end
return doc.text(view.host .. " ...", {colour = "dim", keep = doc.REQUIRED,
truncate = doc.TRUNCATED, name = "link"})
end

local function header(view)
return doc.row({
doc.text(view.title, {colour = "title", keep = doc.REQUIRED, name = "title"}),
doc.spacer({min = 1}),
linkElement(view),
}, {keep = doc.REQUIRED, name = "header"})
end

local function nodeRow(view)
local children = {
doc.text("Node", {colour = "label", keep = doc.REQUIRED, name = "node-label"}),
doc.gap(1),
}

if not view.offer then
children[#children + 1] = doc.text(view.offerWhy
and ("the controller refused: " .. tostring(view.offerWhy))
or "asking the controller what it offers..",
{colour = view.offerWhy and "bad" or "dim", truncate = doc.TRUNCATED,
keep = doc.REQUIRED, name = "offer-state"})
elseif #view.nodes == 0 then
children[#children + 1] = doc.text("no nodes registered",
{colour = "warn", keep = doc.REQUIRED, name = "no-nodes"})
else
for index, node in ipairs(view.nodes) do
if index > 1 then children[#children + 1] = doc.gap(1) end
children[#children + 1] = doc.button(node.label or node.value, {
colour = (view.target == node.value) and "selected" or "action",
action = {kind = "node", node = node.value},


keep = (view.target == node.value) and doc.REQUIRED or (9 - index),
name = "node:" .. node.value,
})
end
children[#children + 1] = doc.spacer()
children[#children + 1] = doc.button("next node", {key = "t",
action = {kind = "cycle-node"}, colour = "dim", keep = 2,
name = "cycle-node", when = {minWidth = 40}})
end

return doc.row(children, {keep = doc.REQUIRED, name = "nodes"})
end

local function cellButton(view, cell)
local item = view.cells[cell]
local usable = view.offer ~= nil and not view.running
return doc.button(item and shortName(item) or "", {
width = "fill",
colour = not usable and "dim" or (item and "action" or "dim"),
action = usable and {kind = "cell", cell = cell} or nil,
key = usable and tostring(cell) or nil,
name = "cell:" .. cell,
})
end




local function gridRows(view)
local rows = {}
for r = 0, 2 do
rows[#rows + 1] = doc.row({
cellButton(view, r * 3 + 1), doc.gap(1),
cellButton(view, r * 3 + 2), doc.gap(1),
cellButton(view, r * 3 + 3),
}, {keep = doc.REQUIRED, name = "grid-row-" .. (r + 1)})
end
return rows
end

local function sliderRow(view)
local min, max = panel.amountRange(view)
local usable = min ~= nil and not view.running
return doc.row({
doc.text("Sets", {colour = "label", keep = doc.REQUIRED, name = "sets-label"}),
doc.gap(1),
doc.button("-", {key = usable and "-" or nil,
colour = usable and "action" or "dim",
action = usable and {kind = "delta", n = -1} or nil, name = "less",
keep = doc.REQUIRED}),
doc.gap(1),
doc.slider({min = min or 1, max = max or 1, value = view.amount,
action = usable and {kind = "amount"} or nil,
colour = usable and "selected" or "dim", name = "amount-bar"}),
doc.gap(1),
doc.button("+", {key = usable and "+" or nil,
colour = usable and "action" or "dim",
action = usable and {kind = "delta", n = 1} or nil, name = "more",
keep = doc.REQUIRED}),
doc.gap(1),


doc.text(tostring(view.amount), {width = #tostring(max or 1),
align = "right", colour = usable and "text" or "dim",
keep = doc.REQUIRED, name = "amount"}),
}, {keep = doc.REQUIRED, name = "sets"})
end

local function actionRow(view)
local blocked = panel.blocked(view)
local label = view.verb
if view.offer and panel.amountRange(view) then
label = ("%s %d sets"):format(view.verb, view.amount)
elseif view.output then
label = ("%s as %s"):format(view.verb, shortName(view.output))
end
return doc.row({


doc.button(label, {key = (not blocked) and "r" or nil,
colour = blocked and "dim" or "good",
action = (not blocked) and {kind = "run"} or nil,
keep = doc.REQUIRED, name = "run"}),
doc.gap(1),
doc.text(blocked or "", {colour = "dim", truncate = doc.TRUNCATED,
keep = 4, name = "why-blocked"}),
doc.spacer(),
doc.button("Clear", {key = "c", action = {kind = "clear"},
keep = 5, name = "clear"}),
}, {keep = doc.REQUIRED, name = "actions"})
end







local function pickerRows(view)
local rows = {}
local cell = view.picking
local current = view.cells[cell]

rows[#rows + 1] = doc.row({
doc.text(("Slot %d"):format(panel.slotOf(cell)), {colour = "title",
keep = doc.REQUIRED, name = "pick-title"}),
doc.gap(1),
doc.text(current and shortName(current) or "empty",
{colour = current and "text" or "dim", truncate = doc.TRUNCATED,
keep = 3, name = "pick-current"}),
doc.spacer(),
doc.text(view.stock and view.source or (view.stockWhy or "reading stock.."),
{colour = view.stockWhy and "bad" or "dim", truncate = doc.TRUNCATED,
keep = 2, name = "pick-source"}),
}, {keep = doc.REQUIRED, name = "pick-head"})

local items = {}
for item in pairs(view.stock or {}) do items[#items + 1] = item end
table.sort(items)



local entries = {}
for _, item in ipairs(items) do
entries[#entries + 1] = {value = item, label = item,
note = tostring(view.stock[item]), selected = current == item}
end
for _, row in ipairs(app.listRows(view.pickList, entries, "pick",
function(entry) return {kind = "pick", item = entry.value} end)) do
rows[#rows + 1] = row
end

if view.stock and #items == 0 then
rows[#rows + 1] = doc.text(view.source .. " holds nothing",
{colour = "warn", keep = 10, name = "pick-empty"})
end



local nav = {
doc.button("back", {key = "backspace", keyLabel = "bksp",
action = {kind = "back"}, keep = doc.REQUIRED, name = "back"}),
doc.gap(1),
doc.button("none", {key = "0", action = {kind = "pick-none"},
keep = 8, name = "none"}),
doc.spacer(),
}
local top = view.pickList.query ~= "" and view.pickList.top
if top then
nav[#nav + 1] = doc.button("pick " .. shortName(top.item), {key = "enter",
colour = "good", action = top, keep = 9, name = "pick-top"})
end
rows[#rows + 1] = doc.row(nav, {keep = doc.REQUIRED, name = "pick-nav"})

return rows
end


local function confirmRows(view)
local params = view.confirming
local parts = {}
for _, slot in ipairs(sortedSlots(params.pattern)) do
parts[#parts + 1] = ("%d=%s"):format(slot, shortName(params.pattern[slot]))
end

local question = params.amount
and ("%s %d sets on %s?"):format(view.verb, params.amount, params.target)
or ("%s on %s?"):format(view.verb, params.target)
local rows = {
doc.text(question,
{colour = "title", wrap = true, keep = doc.REQUIRED, name = "confirm"}),
doc.text(table.concat(parts, " "), {colour = "text", wrap = true, keep = 6,
name = "confirm-pattern"}),
}
if view.note then
rows[#rows + 1] = doc.text(view.note, {colour = "text", wrap = true, keep = 5,
name = "note"})
end
if view.offer and view.offer.destructive then
rows[#rows + 1] = doc.text("This crafts. Material consumed cannot be "
.. "uncrafted.", {colour = "warn", wrap = true, keep = 7,
name = "consequence"})
end
rows[#rows + 1] = doc.row({
doc.button("yes", {key = "y", colour = "good", action = {kind = "yes"},
keep = doc.REQUIRED, name = "yes"}),
doc.gap(1),
doc.button("no", {key = "n", colour = "bad", action = {kind = "no"},
keep = doc.REQUIRED, name = "no"}),
}, {keep = doc.REQUIRED, name = "confirm-actions"})
return rows
end



local function statusRow(view)
if view.running then
local seconds = math.floor((clock(view) - view.running.since) / 1000)
local params = view.running.params
local doing = params.amount and ("running %d sets"):format(params.amount)
or (view.verb:lower() .. "ing")
return doc.text(("%s on %s.. %ds"):format(doing, params.target, seconds),
{colour = "warn", wrap = true, keep = 3, name = "status"})
end

local result = view.result
if not result then
return doc.text("", {colour = "dim", keep = 1, name = "status"})
end

if result.status == panel.COMPLETED and result.fields.recipe then
local recipe = result.fields.recipe
return doc.text(("registered %s: %d %s a set"):format(recipe.label,
recipe.output.count, shortName(recipe.output.item)),
{colour = "good", wrap = true, keep = 3, name = "status"})
elseif result.status == panel.COMPLETED then
local made = {}
for item, count in pairs(result.fields.produced or {}) do
made[#made + 1] = ("%d %s"):format(count, shortName(item))
end
table.sort(made)
return doc.text(("done: %s from %d sets on %s"):format(
#made > 0 and table.concat(made, ", ") or "nothing",
result.params.amount, result.params.target),
{colour = "good", wrap = true, keep = 3, name = "status"})
elseif result.status == panel.TIMED_OUT then
return doc.text(("no answer from %s -- the batch may or may not have "
.. "run: %s"):format(view.host, tostring(result.reason)),
{colour = "warn", wrap = true, keep = 3, name = "status"})
end

local refused = doc.text("refused: " .. tostring(result.reason),
{colour = "bad", wrap = true, keep = 3, name = "status"})
if not (result.fields and result.fields.ambiguous) then return refused end



local kinds = {}
for item in pairs(result.fields.produced or {}) do kinds[#kinds + 1] = item end
table.sort(kinds)
local choices = {doc.text("output:", {colour = "label", keep = doc.REQUIRED,
name = "output-label"})}
for index, item in ipairs(kinds) do
choices[#choices + 1] = doc.gap(1)
choices[#choices + 1] = doc.button(shortName(item), {
colour = (view.output == item) and "selected" or "action",
action = {kind = "output", item = item}, keep = 10 - index,
name = "output:" .. index})
end
return doc.stack({refused, doc.row(choices, {keep = 3, name = "outputs"})},
{keep = 3, name = "status-stack"})
end


function panel.document(view, width, height)
local rows = {header(view), nodeRow(view), doc.rule({keep = 2})}

local body
if view.confirming then
body = confirmRows(view)
elseif view.picking then
body = pickerRows(view)
else
body = gridRows(view)


body[#body + 1] = doc.text("", {keep = 1, name = "breath"})


if not view.offer or panel.amountRange(view) then
body[#body + 1] = sliderRow(view)
end
body[#body + 1] = actionRow(view)
end
for _, row in ipairs(body) do rows[#rows + 1] = row end

rows[#rows + 1] = doc.spacer()
rows[#rows + 1] = statusRow(view)
return doc.stack(rows, {name = "panel"})
end







function panel.settle(view, report)
if not view.picking then return false end
return app.settle(view.pickList, report, "pick")
end







function panel.render(view)
local display = view.display
local width, height = display.size()
local opts = {keys = not display.touchable(), colour = display.colour()}

local document = panel.document(view, width, height)
local grid, report = doc.render(document, width, height, opts)

if grid and panel.settle(view, report) then

grid, report = doc.render(panel.document(view, width, height),
width, height, opts)
end

if not grid then



local diagnostic = doc.text("screen too small: " .. doc.explain(report),
{colour = "bad", wrap = true, keep = doc.REQUIRED, name = "diagnostic"})
grid = doc.render(diagnostic, width, height, opts)
view.lastReport = report
if grid then display.paint(grid) end
return grid
end

view.lastReport = report
display.paint(grid)
return grid
end




function panel.searching(view)
return view.picking and view.pickList or nil
end


function panel.act(view, action)
local kind = action and action.kind
if view.picking and app.page(view.pickList, kind) then return true end

if kind == "node" then
view.target = action.node
return true

elseif kind == "cycle-node" then
if #view.nodes == 0 then return false end
local at = 0
for index, node in ipairs(view.nodes) do
if node.value == view.target then at = index end
end
view.target = view.nodes[(at % #view.nodes) + 1].value
return true

elseif kind == "cell" then
view.picking = action.cell
view.pickList = app.newList()


panel.ask(view, {kind = "stock"})
return true

elseif kind == "pick" then
if not view.picking then return false end
view.cells[view.picking] = action.item
view.picking = nil
view.output = nil
return true

elseif kind == "pick-none" then
if not view.picking then return false end
view.cells[view.picking] = nil
view.picking = nil
return true

elseif kind == "back" then
view.picking = nil
return true

elseif kind == "amount" then
view.amount = clampAmount(view, action.value)
return true

elseif kind == "delta" then
view.amount = clampAmount(view, view.amount + (action.n or 0))
return true

elseif kind == "clear" then
view.cells = {}
view.result = nil
view.output = nil
return true

elseif kind == "output" then
view.output = action.item
return true

elseif kind == "run" then
local params, why = panel.params(view)
if not params then
view.result = {status = panel.REJECTED, reason = why, at = clock(view)}
return true
end
if view.offer.destructive then
view.confirming = params
else
panel.ask(view, {kind = "run", params = params})
end
return true

elseif kind == "yes" then
local params = view.confirming
view.confirming = nil
if params then panel.ask(view, {kind = "run", params = params}) end
return true

elseif kind == "no" then
view.confirming = nil
return true
end

return false
end








function panel.handle(view, event, grid)
if panel.searching(view) and app.type(view.pickList, event) then return true end
if not input.heard(event) then return false end
local action = input.actionFor(grid, event)
if not action then return false end
return panel.act(view, action)
end









function panel.exchange(view, job)
local body, opts

if job.kind == "offer" then
view.offerAskedAt = clock(view)
body = {command = "offer", name = view.action}
opts = panel.READ
elseif job.kind == "stock" then
body = {command = "stock", path = view.source}
opts = panel.READ
elseif job.kind == "run" then
body = {command = view.action, operator = true}
for key, value in pairs(job.params) do body[key] = value end
opts = panel.RUN
view.running = {params = job.params, since = clock(view)}
view.result = nil
else
return false
end

local answer = view.transport.request(body, opts) or {}
panel.apply(view, job, answer)
return true
end


function panel.apply(view, job, answer)
local now = clock(view)

if answer.src then
view.link = {state = "ok", at = now}
elseif answer.status == panel.TIMED_OUT or answer.status == panel.REJECTED then
view.link = {state = "down", reason = answer.reason, at = now}
end

if job.kind == "offer" then
local decl = answer.status == panel.COMPLETED
and type(answer.actions) == "table" and answer.actions[1]
if not decl then
view.offerWhy = answer.reason or answer.status or "no answer"
return
end
view.offer = decl
view.offerWhy = nil

local target = panel.parameter(view, "target")
view.nodes = {}
if target and type(target.choices) == "table" and not target.choices.source then
for _, entry in ipairs(target.choices) do
if type(entry) == "table" then
view.nodes[#view.nodes + 1] = {value = entry.value,
label = entry.label or entry.value}
else
view.nodes[#view.nodes + 1] = {value = entry, label = entry}
end
end
end

local stillThere = false
for _, node in ipairs(view.nodes) do
if node.value == view.target then stillThere = true end
end
if not stillThere then view.target = nil end
if not view.target and #view.nodes == 1 then
view.target = view.nodes[1].value
end
view.amount = clampAmount(view, view.amount)

elseif job.kind == "stock" then
if answer.status == panel.COMPLETED and type(answer.stock) == "table" then
view.stock = answer.stock
view.stockWhy = nil
else
view.stockWhy = ("%s: %s"):format(view.source,
tostring(answer.reason or answer.status or "no answer"))
end

elseif job.kind == "run" then
view.running = nil
view.result = {
status = answer.status or panel.REJECTED,
reason = answer.reason,
fields = answer,
params = job.params,
at = now,
}
end
end



function panel.nextJob(view)
local job = table.remove(view.queue, 1)
if not job and panel.offerDue(view) then job = {kind = "offer"} end
return job
end


function panel.serve(view, opts)
opts = opts or {}
while true do
local job = panel.nextJob(view)
if job then
panel.exchange(view, job)
else
sleep(opts.idle or 0.2)
end
end
end










function panel.transport(host)
local actions = require("mfg.common.actions")
return {
request = function(body, opts)
local status, fields = actions.invoke("transmit", {
target = host,
protocol = "mfg-scada",
content = textutils.serialize(body),
timeout = opts and opts.timeout,
attempts = opts and opts.attempts,
}, {by = "hmi"})

local reply = fields and fields.reply
if type(reply) ~= "table" then



reply = {status = status, reason = fields and fields.reason}
end
return reply
end,
}
end




function panel.run(view, opts)
opts = opts or {}
parallel.waitForAny(
function() panel.serve(view, opts) end,
function()
input.drive(view.display,
function() return panel.render(view) end,
function(event, grid) return panel.handle(view, event, grid) end,
{wait = opts.wait or 1})
end)
end

return panel
]],
["mfg/hmi/panes.lua"] = [[
















local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")

local panes = {}











panes.TOP = "top"
panes.LEFT = "left"























panes.LEADER = "tab"


panes.CYCLE = panes.LEADER

function panes.new(opts)
opts = opts or {}
return {
title = opts.title,
edge = opts.edge or panes.TOP,
width = opts.width or 12,
apps = {},
order = {},
current = nil,
}
end









function panes.add(host, app)
if type(app) ~= "table" or type(app.name) ~= "string" then
return nil, "an app needs a name"
end
if type(app.render) ~= "function" then
return nil, ("app %s needs a render function"):format(app.name)
end
if host.apps[app.name] then
return nil, ("app %s is already declared"):format(app.name)
end

host.apps[app.name] = app
host.order[#host.order + 1] = app.name
if not host.current then host.current = app.name end
return app
end

function panes.select(host, name)
if not host.apps[name] then return false, "no such app: " .. tostring(name) end
host.current = name
return true
end

function panes.app(host)
return host.apps[host.current]
end



local function indexElement(host, across)
local children = {}





local heading = host.title
if host.leaderPending then
heading = (heading and (heading .. " ") or "") .. "TAB.."
elseif heading then
heading = heading .. " tab+"
end

if heading and across then
children[#children + 1] = doc.text(heading, {
colour = host.leaderPending and "warn" or "label",
keep = 3, name = "title"})
children[#children + 1] = doc.gap(1)
end

for i, name in ipairs(host.order) do
local app = host.apps[name]
if across and i > 1 then children[#children + 1] = doc.gap(1) end

local usable = (app.ready == nil) or app.ready()
children[#children + 1] = doc.button(app.label or name, {


key = input.scoped(panes.LEADER, app.key or tostring(i)),
keyLabel = app.key or tostring(i),
colour = (host.current == name) and "selected"
or (usable and "action" or "dim"),
action = {kind = "app", app = name},


keep = (host.current == name) and doc.REQUIRED or (9 - i),
name = name,
})
end

if across then
return doc.row(children, {keep = doc.REQUIRED, name = "index"})
end
return doc.stack(children, {width = host.width, keep = doc.REQUIRED,
name = "index"})
end

panes.indexElement = indexElement








function panes.document(host, width, height)
local app = panes.app(host)
if not app then
return doc.stack({
doc.text("NO APPS", {colour = "bad", keep = doc.REQUIRED}),
}, {name = "empty"})
end

if host.edge == panes.LEFT then
local paneWidth = math.max(1, width - host.width - 1)
return doc.row({
indexElement(host, false),
doc.gap(1),
app.render(paneWidth, height),
}, {name = "host"})
end

local paneHeight = math.max(1, height - 1)
return doc.stack({
indexElement(host, true),
app.render(width, paneHeight),
}, {name = "host"})
end

function panes.render(host, width, height, opts)
return doc.render(panes.document(host, width, height), width, height, opts)
end








function panes.shadowed(host, grid)
local out = {}
for _, name in ipairs(host.order) do
local app = host.apps[name]
if app.key then
local bound = (grid.keys or {})[input.scoped(panes.LEADER, app.key)]
if not bound or bound.kind ~= "app" or bound.app ~= name then
out[#out + 1] = {app = name, key = app.key}
end
end
end
return out
end





function panes.handle(host, event, grid)
if not event then return false end

local isLeader = event.kind == "key" and keys
and event.key == keys[panes.LEADER]


if isLeader and host.leaderPending then
host.leaderPending = false
local at = 1
for i, name in ipairs(host.order) do
if name == host.current then at = i end
end
local nextName = host.order[(at % #host.order) + 1]
if nextName then panes.select(host, nextName) end
return true, {kind = "app", app = host.current}
end



if isLeader then
host.leaderPending = true
return true, {kind = "leader"}
end





if host.leaderPending then
host.leaderPending = false
local scoped = input.actionFor(grid, event, {leader = panes.LEADER})
if scoped and scoped.kind == "app" then
panes.select(host, scoped.app)
return true, scoped
end
return false
end

local action = input.actionFor(grid, event)
if not action then



local app = panes.app(host)
if app and app.handle then return app.handle(nil, event) end
return false
end

if action.kind == "app" then
panes.select(host, action.app)
return true, action
end

local app = panes.app(host)
if app and app.handle then return app.handle(action, event), action end
return false, action
end

return panes
]],
["mfg/hmi/services.lua"] = [[



























local services = require("mfg.common.services")

local hmi = {}



local function displayBackend()
local hal = require("mfg.common.hal")
if hal.mode() == "mock" then return require("mfg.hmi.hal.display_mock") end
return require("mfg.hmi.hal.display_real")
end

function hmi.declare(manager, ctx)




local onTerminal = displayBackend().attached() == "terminal"




services.declare(manager, {
name = "panel",
requires = {"netstack"},
ready = ctx.admitted,
terminal = onTerminal,
start = function()
local panel = require("mfg.hmi.panel")
