["mfg/hmi/storagepanel.lua"] = [[











local doc = require("mfg.hmi.doc")
local input = require("mfg.hmi.input")
local app = require("mfg.hmi.app")

local storage = {}

storage.EVERY = 5
storage.READ = {timeout = 3, attempts = 2}

storage.TAKE = {timeout = 20, attempts = 1}

function storage.new(opts)
opts = opts or {}
return {
host = opts.host or "mfg",
display = opts.display,
transport = opts.transport,
now = opts.now,

items = nil,
pending = {}, waiting = {},
bound = {},
readWhy = nil,
readAt = nil,

offer = nil,

item = nil,
count = 1,
list = app.newList(),

sending = nil,
result = nil,
link = {state = "unknown"},
queue = {},
}
end

local function sortedItems(view)
local names = {}
for item in pairs(view.items or {}) do names[#names + 1] = item end
table.sort(names)
return names
end

local function freeOf(view, item)
local entry = view.items and view.items[item]
return entry and entry.free or 0
end

function storage.blocked(view)
if view.sending then return "a withdrawal is being sent" end
if not view.items then return "reading the pool.." end
if view.bound.output == false then return "bind /io/out on the controller" end
if not view.item then return "pick an item" end
if freeOf(view, view.item) < 1 then return "none of it is free" end
return nil
end




function storage.refresh(view)
view.readAt = nil
end

function storage.nextJob(view)
local job = table.remove(view.queue, 1)
if job then return job end
if not view.readAt or (app.clock(view) - view.readAt) >= storage.EVERY * 1000 then
return {kind = "read"}
end
return nil
end

function storage.exchange(view, job)
local body, opts
if job.kind == "read" then
view.readAt = app.clock(view)
body, opts = {command = "available"}, storage.READ
elseif job.kind == "withdraw" then
body = {command = "withdraw", item = job.item, count = job.count, operator = true}
opts = storage.TAKE
view.sending = {item = job.item, count = job.count, since = app.clock(view)}
view.result = nil
else
return false
end
storage.apply(view, job, view.transport.request(body, opts) or {})
return true
end

function storage.apply(view, job, answer)
app.noteLink(view, answer)
if job.kind == "read" then
if answer.status == app.COMPLETED and type(answer.items) == "table" then
view.items, view.readWhy = answer.items, nil
view.pending, view.waiting = answer.pending or {}, answer.waiting or {}
view.bound = answer.bound or {}
view.offer = view.offer or {name = "available"}

if view.item then
view.count = app.clamp(view.count, 1, math.max(1, freeOf(view, view.item)))
end
else
view.readWhy = tostring(answer.reason or answer.status or "no answer")
end
elseif job.kind == "withdraw" then
view.sending = nil
view.result = {status = answer.status or app.REJECTED, reason = answer.reason,
fields = answer, item = job.item, count = job.count}
view.readAt = nil
end
end



local function summary(label, items, name)
local parts = {}
for item, count in pairs(items or {}) do
parts[#parts + 1] = ("%d %s"):format(count, app.shortName(item))
end
table.sort(parts)
if #parts == 0 then return nil end
return doc.text(("%s: %s"):format(label, table.concat(parts, ", ")),
{colour = "dim", truncate = doc.TRUNCATED, keep = 5, name = name})
end

local function statusRow(view)
if view.sending then
return doc.text(("withdrawing %d %s.."):format(view.sending.count,
app.shortName(view.sending.item)),
{colour = "warn", wrap = true, keep = 8, name = "status"})
end
local result = view.result
if not result then return doc.text("", {keep = 1, name = "status"}) end
local fields = result.fields or {}
if result.status == app.COMPLETED then
local text = ("%d %s in /io/out"):format(fields.moved or 0,
app.shortName(result.item))
if fields.short then text = text .. " -- " .. tostring(fields.reason) end
return doc.text(text, {colour = fields.short and "warn" or "good", wrap = true,
keep = 8, name = "status"})
elseif result.status == app.TIMED_OUT then
return doc.text(("no answer from %s -- look in /io/out before asking again")
:format(view.host), {colour = "warn", wrap = true, keep = 8, name = "status"})
end
return doc.text("refused: " .. tostring(result.reason),
{colour = "bad", wrap = true, keep = 8, name = "status"})
end

function storage.document(view, width, height)
local rows = {app.header(view, "STORAGE"), doc.rule({keep = 2})}

if not view.items then
rows[#rows + 1] = doc.text(view.readWhy and ("the controller refused: "
.. view.readWhy) or "reading the pool..", {colour = view.readWhy and "bad"
or "dim", wrap = true, keep = doc.REQUIRED, name = "read-state"})
else
local entries = {}
for _, item in ipairs(sortedItems(view)) do
local entry = view.items[item]
local label = ("%s  %d free"):format(app.shortName(item), entry.free)
if entry.promised > 0 then
label = label .. (" (%d promised)"):format(entry.promised)
end
entries[#entries + 1] = {value = item, label = label,
selected = view.item == item}
end
if #entries == 0 then
rows[#rows + 1] = doc.text("the pool is empty -- put things in /io/in",
{colour = "warn", wrap = true, keep = 20, name = "empty"})
end
for _, row in ipairs(app.listRows(view.list, entries, "item",
function(entry) return {kind = "item", item = entry.value} end)) do
rows[#rows + 1] = row
end

local blocked = storage.blocked(view)
rows[#rows + 1] = app.quantityRow(view.count, not view.sending, "Take")
rows[#rows + 1] = doc.row({
doc.button("Withdraw", {key = (not blocked) and "enter" or nil,
colour = blocked and "dim" or "good",
action = (not blocked) and {kind = "withdraw"} or nil,
keep = doc.REQUIRED, name = "withdraw"}),
doc.gap(1),
doc.text(blocked or "", {colour = "dim", truncate = doc.TRUNCATED,
keep = 4, name = "why-blocked"}),
}, {keep = doc.REQUIRED, name = "actions"})
end

rows[#rows + 1] = statusRow(view)
rows[#rows + 1] = summary("coming in", view.pending, "pending")
or doc.text("", {keep = 1, name = "pending"})
rows[#rows + 1] = summary("in /io/out", view.waiting, "waiting")
or doc.text("", {keep = 1, name = "waiting"})
rows[#rows + 1] = doc.spacer()
return doc.stack(rows, {name = "storage"})
end

function storage.settle(view, report)
return app.settle(view.list, report, "item")
end



function storage.act(view, action)
local kind = action and action.kind
if app.page(view.list, kind) then return true end
if kind == "item" then
view.item = action.item
view.count = app.clamp(view.count, 1, math.max(1, freeOf(view, action.item)))
return true
elseif kind == "delta" then
local max = view.item and math.max(1, freeOf(view, view.item)) or nil
view.count = app.clamp(view.count + (action.n or 0), 1, max)
return true
elseif kind == "withdraw" then
local why = storage.blocked(view)
if why then
view.result = {status = app.REJECTED, reason = why}
return true
end

app.ask(view, {kind = "withdraw", item = view.item, count = view.count})
return true
end
return false
end


function storage.searching(view)
return view.items and view.list or nil
end


function storage.handle(view, event, grid)
if storage.searching(view) and app.type(view.list, event) then return true end
if not input.heard(event) then return false end
local action = input.actionFor(grid, event)
if not action then return false end
return storage.act(view, action)
end

return storage
]],
["net.lua"] = [[















local routing = require("routing")
local netcrypt = require("netcrypt")
local netkeys = require("netkeys")
local ip = require("ip")

local net = {}

local REGISTRY = "/services"

local registry = nil
local reverse = nil

local function load()
if registry then return registry end

registry, reverse = {}, {}
if not fs.exists(REGISTRY) then return registry end

local handle = fs.open(REGISTRY, "r")
if not handle then return registry end
local data = handle.readAll()
handle.close()

for line in data:gmatch("[^\r\n]+") do

local name, port = line:match("^%s*([%w_%-]+)%s+(%d+)")
if name and not line:match("^%s*#") then
registry[name] = tonumber(port)
reverse[tonumber(port)] = name
end
end
return registry
end

function net.services()
return load()
end

function net.port(name)
return load()[name]
end

function net.nameOf(port)
load()
return reverse[port]
end


function net.reload()
registry, reverse = nil, nil
return load()
end

local function portFor(name)
if type(name) ~= "string" then
return nil, "service name must be a string"
end
local port = net.port(name)
if not port then
return nil, ("unknown service '%s' -- add it to %s"):format(name, REGISTRY)
end
return port
end




function net.serve(name)
local port, err = portFor(name)
if not port then return false, err end
return routing.bind(port)
end

function net.unserve(name)
local port = net.port(name)
if port then routing.unbind(port) end
end






function net.parseAddress(text)
return ip.parse(text)
end

function net.formatAddress(address)
return ip.format(address)
end









local function resolveName(name)
local record, err = routing.lookupName(name)
if not record then return nil, err end

local voucher = netkeys.fromHex(record.voucher or "")
if not voucher then return nil, ("no voucher for '%s'"):format(name) end



local address, pk, vouchedName = netkeys.verifyVoucher(
voucher, netkeys.decodeChain(record.chain))
if not address then return nil, "voucher rejected: " .. tostring(pk) end
if vouchedName ~= name then
return nil, ("voucher names '%s', not '%s'"):format(
tostring(vouchedName), name)
end

return address
end








local function candidates(name)
if name:find(".", 1, true) then return {name} end

local zone = net.zone()
if zone == "" then return {name} end

local out = {}
while zone ~= "" do
out[#out + 1] = name .. "." .. zone
zone = zone:match("%.(.+)$") or ""
end
out[#out + 1] = name
return out
end


local function addressFor(target)
if type(target) == "number" then return target end
if type(target) ~= "string" then
return nil, "expected an address or a hostname"
end



local literal = ip.parse(target)
if literal then return literal end

local err
for _, candidate in ipairs(candidates(target)) do
local address
address, err = resolveName(candidate)
if address then return address end
end
return nil, err
end



function net.resolve(target)
local address, err = addressFor(target)
if not address then return nil, err end
return ip.format(address)
end



function net.send(target, name, body)
local port, err = portFor(name)
if not port then return false, err end

local address, resolveErr = addressFor(target)
if not address then return false, resolveErr end


return netcrypt.send(address, port, body, port)
end


function net.receive(name, timeout)
local port = nil
if name ~= nil then
local err
port, err = portFor(name)
if not port then return nil, err end
end

local packet = netcrypt.receive(port, timeout)
if not packet then return nil end

return {

src = ip.format(packet.src),
service = net.nameOf(packet.dport) or packet.dport,
body = packet.body,


encrypted = packet.encrypted,


from = packet.name,
}
end




function net.nameFor(target)
local address, addrErr = addressFor(target)
if not address then return nil, addrErr end

local record, err = routing.lookup(address)
if not record then return nil, err end

local voucher = netkeys.fromHex(record.voucher or "")
if not voucher then return nil, "no voucher for that address" end

local vouchedAddress, pk, name = netkeys.verifyVoucher(
voucher, netkeys.decodeChain(record.chain))
if not vouchedAddress then return nil, "voucher rejected: " .. tostring(pk) end
if vouchedAddress ~= address then
return nil, "voucher describes a different address"
end

return name ~= "" and name or nil
end

function net.isEncrypted(name)
local port = net.port(name)
return port ~= nil and netcrypt.isEncrypted(port)
end


function net.address()
local address = routing.address()
return address and ip.format(address) or nil
end



function net.hostname()
return routing.localName()
end






function net.zone()
local own = netkeys.zone()
if own ~= "" then return own end

local name = routing.localName()
if not name then return "" end
return name:match("%.(.+)$") or ""
end


function net.whoami()
return net.hostname() or net.address() or "unassigned"
end

function net.ready()
return netcrypt.isRunning() and routing.address() ~= nil
end

return net
]],
["netadmin.lua"] = [[

































local random = require("ccryptolib.random")
local netkeys = require("netkeys")
local ip = require("ip")
local band = require("band")

local args = {...}
local cmd = args[1]


if not random.isInit() then
write("seeding crypto rng... ")
random.initWithTiming()
print("done")
end

netkeys.init()

local function findDisk()
for i = 0, 5 do
local path = i == 0 and "/disk" or ("/disk%d"):format(i)
if fs.exists(path) and fs.isDir(path) then return path end
end
return nil
end




local function parseKeyFile(path)
local f = fs.open(path, "r")
if not f then return nil, "could not open " .. path end
local data = f.readAll()
f.close()

local bare = data:gsub("%s", "")
if #bare == 64 and not bare:find("%X") then
return {exchange = bare}
end

local keys = {}
for label, hex in data:gmatch("(%a+)%s+(%x+)") do
if #hex == 64 then keys[label] = hex end
end


keys.name = data:match("name%s+([%w_%-]+)")
if not keys.exchange then
return nil, path .. " has no exchange key"
end
return keys
end

local function readKeyFile(path)
local keys, err = parseKeyFile(path)
if not keys then return nil, err end
return keys.exchange
end



local function resolveKey(arg)
if type(arg) ~= "string" or arg == "" then
return nil, "expected a key or a file path"
end

local trimmed = arg:gsub("%s", "")
if #trimmed == 64 and not trimmed:find("%X") then return trimmed end

if not fs.exists(arg) then
return nil, ("no such file: %s (and it is not a 64-character key)"):format(arg)
end
if fs.isDir(arg) then return nil, arg .. " is a directory" end

return readKeyFile(arg)
end




local function usage()
local lines = {
"netadmin key",
"netadmin role <server|client|both>",
"netadmin hostname [name]    what this computer asks to be called",
"netadmin substrate <rednet|hopnet>",
"",
"addressing",
"  netadmin ip               this computer's addressing",
"  netadmin iface [<addr>/<len> [modem] | del <addr>]",
"  netadmin subnet [<cidr> [via <ip>] [band <base> <size>] | del <cidr>]",
"  netadmin address <hex|path> <ip>              (server)",
"  netadmin band [<base> <size> | del]  hop channels this subnet uses",
"",
"identity",
"  netadmin export [path]    write our public key out",
"  netadmin pin <hex|path>                       (client)",
"  netadmin allow <hex|path>                     (server)",
"  netadmin name <hex|path> <hostname>           (server)",
"  netadmin revoke <hex>",
"  netadmin chain            the delegation this computer holds",
"  netadmin list",
"",
"ports",
"  netadmin encrypt <service|port>   require encryption",
"  netadmin plain <service|port>     stop requiring it",
}
textutils.pagedPrint(table.concat(lines, "\n"))
end

if cmd == "key" then
print(netkeys.toHex(netkeys.publicKey()))

elseif cmd == "role" then
if args[2] ~= "server" and args[2] ~= "client" and args[2] ~= "both" then
printError("role must be 'server', 'client' or 'both'")
print("'both' is a sub-server: it admits its own subnet and is")
print("itself a client of its parent")
return
end
netkeys.setRole(args[2])
print("role set to " .. args[2])

elseif cmd == "hostname" then
if not args[2] then
print("hostname: " .. (netkeys.hostname() or "(unset)"))
return
end
local ok, reason = pcall(netkeys.setHostname, args[2])
if not ok then
printError(tostring(reason))
return
end
print("hostname set to " .. args[2])
print("re-export so the server sees it: netadmin export")

elseif cmd == "substrate" then
if args[2] ~= "rednet" and args[2] ~= "hopnet" then
printError("substrate must be 'rednet' or 'hopnet'")
print("current: " .. netkeys.substrate())
return
end
netkeys.setSubstrate(args[2])
print("substrate set to " .. args[2])
print("restart netstart for it to take effect")

elseif cmd == "encrypt" or cmd == "plain" then


local target = args[2] or ""
local port = tonumber(target)
if not port then
local ok, net = pcall(require, "net")
port = ok and net.port(target) or nil
end
if not port then
printError(("expected a port number or a known service, got '%s'"):format(target))
return
end
netkeys.setPortEncrypted(port, cmd == "encrypt")
if cmd == "encrypt" then
print(("port %d now requires encryption"):format(port))
print("plaintext arriving on it will be refused")
else
print(("port %d no longer requires encryption"):format(port))
end
print("restart netstart for it to take effect")

elseif cmd == "chain" then
local chain = netkeys.chain()
local network, prefix = netkeys.authority()

print("grant: " .. ip.formatCidr(network, prefix))
if #chain == 0 then
print("no certificates -- this computer is the root authority")
return
end



for i, cert in ipairs(chain) do
local fields = netkeys.parseCert(cert)
if fields then
print(("%d. %-18s %s"):format(i,
ip.formatCidr(fields.network, fields.prefix),
fields.name ~= "" and fields.name or "(unnamed)"))
print(("   signs with %s..."):format(
netkeys.toHex(fields.signer):sub(1, 16)))
end
end

elseif cmd == "ip" then


local ipnet = require("ipnet")

print("link-local: " .. ip.format(ip.linkLocal(os.getComputerID())))

local ifaces = ipnet.interfaces()
if #ifaces == 0 then
print("address:    (none -- run netstart, or declare one with 'iface')")
else
for _, iface in ipairs(ifaces) do
print(("address:    %s  %s"):format(
ip.formatCidr(iface.address, iface.prefix), iface.modem or "(all modems)"))
end
end

local gateway = ipnet.gateway()
print("gateway:    " .. (gateway and ip.format(gateway) or "(none)"))

local routes = ipnet.routes()
if #routes > 0 then
print()
print("routes:")
for _, route in ipairs(routes) do
print(("  %-18s via %s"):format(
ip.formatCidr(route.network, route.prefix), ip.format(route.via)))
end
end

print()
print("declared in /net/interfaces:")
local declared = netkeys.interfaces()
if #declared == 0 then
print("  (none -- this computer takes what the server assigns)")
end
for _, iface in ipairs(declared) do
print(("  %s %s"):format(
ip.formatCidr(iface.address, iface.prefix), iface.modem or ""))
end

elseif cmd == "iface" then
if not args[2] then
local declared = netkeys.interfaces()
if #declared == 0 then print("no interfaces declared") end
for _, iface in ipairs(declared) do
print(("%s %s"):format(
ip.formatCidr(iface.address, iface.prefix), iface.modem or ""))
end
return
end

if args[2] == "del" then
local addr = ip.parse(args[3] or "")
if not addr then
printError("expected an address to remove")
return
end
if netkeys.removeInterface(addr) then
print("removed " .. ip.format(addr))
else
printError("no interface at " .. ip.format(addr))
end
return
end

local addr, prefix = ip.parseCidr(args[2])
if not addr then
printError(tostring(prefix))
print("expected something like 10.0.1.1/24")
return
end

local modem = args[3]
if modem and peripheral.getType(modem) ~= "modem" then
printError(("'%s' is not a modem on this computer"):format(modem))
return
end

netkeys.addInterface(addr, prefix, modem)
print(("interface %s on %s"):format(
ip.formatCidr(addr, prefix), modem or "every modem"))
print("restart netstart for it to take effect")

elseif cmd == "subnet" then
if not args[2] then
for _, subnet in ipairs(netkeys.subnets()) do
print(("%-18s %s"):format(ip.formatCidr(subnet.network, subnet.prefix),
subnet.via and ("via " .. ip.format(subnet.via)) or "(ours)"))
end
return
end

if args[2] == "del" then
local network, prefix = ip.parseCidr(args[3] or "")
if not network then
printError("expected a subnet to remove, like 10.0.1.0/24")
return
end
if netkeys.removeSubnet(network, prefix) then
print("removed " .. ip.formatCidr(ip.network(network, prefix), prefix))
else
printError("no such subnet")
end
return
end

local network, prefix = ip.parseCidr(args[2])
if not network then
printError(tostring(prefix))
print("expected something like 10.0.1.0/24")
return
end



local via = nil
if args[3] == "via" then
via = ip.parse(args[4] or "")
if not via then
printError("expected an address after 'via'")
return
end
end



local delegated = nil
for i = 3, #args - 2 do
if args[i] == "band" then
local parsed, bandErr = band.parse(args[i + 1], args[i + 2])
if not parsed then
printError(tostring(bandErr))
return
end
delegated = parsed
end
end






if delegated then
local own = netkeys.band()
if not band.contains(own, delegated) then
printError(("band %s is outside our own %s"):format(
band.format(delegated), band.format(own)))
print("set this computer's band first: netadmin band <base> <size>")
return
end
end

netkeys.setSubnet(network, prefix, via, delegated)
print(("subnet %s %s"):format(
ip.formatCidr(ip.network(network, prefix), prefix),
via and ("via " .. ip.format(via)) or "served here"))
if delegated then print("  band " .. band.format(delegated)) end
print("clients pick up new routes on their next handshake")

elseif cmd == "band" then
if not args[2] then
local own = netkeys.band()
print("this computer serves: " .. band.format(own))
print(("valid range is %d..%d"):format(band.FLOOR, band.CEILING))
print("below " .. band.FLOOR .. " is fixed-channel space (computer ids)")
for _, subnet in ipairs(netkeys.subnets()) do
if subnet.band then
print(("  %-18s %s"):format(
ip.formatCidr(subnet.network, subnet.prefix),
band.format(subnet.band)))
end
end
return
end

if args[2] == "del" then
netkeys.setBand(nil)
print("band cleared -- links derive over the whole channel space again")
return
end

local parsed, bandErr = band.parse(args[2], args[3])
if not parsed then
printError(tostring(bandErr))
print("usage: netadmin band <base> <size>")
print(("  root is normally %d %d"):format(band.ROOT.base, band.ROOT.size))
return
end

netkeys.setBand(parsed)
print("band " .. band.format(parsed))
print("restart netstart for it to take effect")

elseif cmd == "address" then
local hex, keyErr = resolveKey(args[2])
if not hex then
printError(tostring(keyErr))
return
end

local addr = ip.parse(args[3] or "")
if not addr then
printError("expected an address, like 10.0.0.7")
return
end

netkeys.setAddress(hex, addr)
print(("%s... pinned to %s"):format(hex:sub(1, 16), ip.format(addr)))
print("it takes effect on that computer's next handshake")

elseif cmd == "export" then
local target = args[2] or findDisk()
if not target then
printError("no disk found -- give a path, or insert a floppy")
return
end


local path = target
if fs.exists(target) and fs.isDir(target) then
path = fs.combine(target, ("key-%d.hex"):format(os.getComputerID()))
end

local out = {"exchange " .. netkeys.toHex(netkeys.publicKey())}




if netkeys.isServer() then
out[#out + 1] = "sign " .. netkeys.toHex(netkeys.signingKey())
end





local anchor = netkeys.signerKey()
if anchor then out[#out + 1] = "root " .. netkeys.toHex(anchor) end


local hostname = netkeys.hostname()
if hostname then out[#out + 1] = "name " .. hostname end

local f = fs.open(path, "w")
if not f then
printError("could not write " .. path)
return
end
f.write(table.concat(out, "\n"))
f.close()

print("public keys written to " .. path)
for _, line in ipairs(out) do print("  " .. line:sub(1, 24) .. "...") end
print("all public data -- no secret ever leaves this computer")

elseif cmd == "pin" then
local keys, err
local arg = args[2] or ""
local trimmed = arg:gsub("%s", "")

if #trimmed == 64 and not trimmed:find("%X") then
keys = {exchange = trimmed}
elseif fs.exists(arg) and not fs.isDir(arg) then
keys, err = parseKeyFile(arg)
else
err = ("no such file: %s (and it is not a 64-character key)"):format(arg)
end

if not keys then
printError(tostring(err))
return
end

netkeys.setServerKey(keys.exchange)
print("exchange key pinned: " .. keys.exchange:sub(1, 16) .. "...")






local anchor = keys.root or keys.sign
if anchor then
netkeys.setSignerKey(anchor)
print("trust anchor pinned: " .. anchor:sub(1, 16) .. "...")
if keys.root and keys.sign and keys.root ~= keys.sign then
print("(that server is itself a delegate of this anchor)")
end
else
printError("no signer key in that file -- peer sessions will not work")
print("re-export from the server once its role is set")
end

print("a server without the matching private keys can no longer")
print("complete a handshake with this computer")

elseif cmd == "allow" then
local target = args[2]





local function admit(hex, proposed, source)
netkeys.allow(hex)
print(("allowed %s...%s"):format(hex:sub(1, 16), source and "  (" .. source .. ")" or ""))

if not proposed then return end

local assigned, reason = netkeys.assignName(hex, proposed)
if not assigned then
printError("  " .. tostring(reason))
print("  admitted anyway; assign a name with 'netadmin name'")
elseif assigned ~= proposed then


print(("  named '%s'  (asked for '%s')"):format(assigned, proposed))
else
print(("  named '%s'"):format(assigned))
end
end


if type(target) == "string" and fs.exists(target) and fs.isDir(target) then
local count = 0
for _, file in ipairs(fs.list(target)) do
if file:match("%.hex$") then
local keys, err = parseKeyFile(fs.combine(target, file))
if keys then
admit(keys.exchange, keys.name, file)
count = count + 1
else
printError(tostring(err))
end
end
end
if count == 0 then printError("no .hex key files in " .. target) end
return
end


local override = args[3]
local proposed = override

if not override and fs.exists(target or "") and not fs.isDir(target) then
local keys = parseKeyFile(target)
proposed = keys and keys.name or nil
end

local hex, err = resolveKey(target)
if not hex then
printError(tostring(err))
return
end
admit(hex, proposed)

elseif cmd == "name" then
local hex, err = resolveKey(args[2])
if not hex then
printError(tostring(err))
return
end
local ok, reason = pcall(netkeys.setName, hex, args[3] or "")
if not ok then
printError(tostring(reason))
return
end
print(("%s... is now '%s'"):format(hex:sub(1, 16), args[3]))
print("restart the server for it to appear in new vouchers")

elseif cmd == "revoke" then
local hex, err = resolveKey(args[2])
if not hex then
printError(tostring(err))
return
end
netkeys.revoke(hex)
print("revoked " .. hex:sub(1, 16) .. "...")

elseif cmd == "list" then
print("role:    " .. tostring(netkeys.role()))
print("subst:   " .. netkeys.substrate())

local ports = {}
for port in pairs(netkeys.encryptedPorts()) do ports[#ports + 1] = port end
table.sort(ports)
print("crypt:   " .. (#ports > 0 and table.concat(ports, " ") or "no ports"))
print("our key: " .. netkeys.toHex(netkeys.publicKey()))

if netkeys.isServer() then
print("signer:  " .. netkeys.toHex(netkeys.signingKey()))

local network, prefix = netkeys.authority()
local chain = netkeys.chain()
print(("grant:   %s%s"):format(ip.formatCidr(network, prefix),
#chain == 0 and "   (root -- nothing above us)" or ""))
end

local pinned = netkeys.serverKey()
print("pinned:  " .. (pinned and netkeys.toHex(pinned) or "none"))

local signer = netkeys.signerKey()
print("verify:  " .. (signer and netkeys.toHex(signer) or "none"))

print()
print("allowlist:")
local any = false
for hex in pairs(netkeys.allowed()) do
print("  " .. hex)
any = true
end
if not any then print("  (empty)") end

print()
print("subnets:")
for _, subnet in ipairs(netkeys.subnets()) do
print(("  %-18s %s"):format(ip.formatCidr(subnet.network, subnet.prefix),
subnet.via and ("via " .. ip.format(subnet.via)) or "(ours)"))
end

print()
print("addresses:")
any = false
local names = netkeys.names()
for hex, addr in pairs(netkeys.addresses()) do
print(("  %-15s %-16s %s..."):format(
ip.format(addr), names[hex] or "(unnamed)", hex:sub(1, 16)))
any = true
end
if not any then print("  (none assigned)") end

else
usage()
end
]],
["netcrypt.lua"] = [[




















local routing = require("routing")
local peersession = require("peersession")

local netcrypt = {}

local SEND_TIMEOUT = 30

local state = _G.__netcrypt
if not state then
state = {running = false, debug = false}
_G.__netcrypt = state
end

state.encrypted = state.encrypted or {}

local pendingSends = {}
local nextRequest = 0

local function log(...)
if state.debug then os.queueEvent("netcrypt_debug", ...) end
end

function netcrypt.setDebug(enabled)
state.debug = enabled
end



function netcrypt.setEncrypted(port, enabled)
state.encrypted[port] = enabled and true or nil
end





function netcrypt.setPolicy(ports)
local replacement = {}
for port in pairs(ports) do replacement[port] = true end
state.encrypted = replacement
end

function netcrypt.isEncrypted(port)
return state.encrypted[port] == true
end

function netcrypt.encryptedPorts()
return state.encrypted
end



local function toHex(s)
return (s:gsub(".", function(c) return ("%02x"):format(c:byte()) end))
end

local function fromHex(h)
if type(h) ~= "string" or #h % 2 ~= 0 or h:find("%X") then return nil end
return (h:gsub("%x%x", function(b) return string.char(tonumber(b, 16)) end))
end



local function deliver(request)
local port = request.dstPort

if not netcrypt.isEncrypted(port) then
return routing.send(request.dst, port,
{enc = false, d = request.body}, request.srcPort)
end

local sealed, counter = peersession.seal(request.dst, textutils.serialize(request.body))
if not sealed then return false, counter end

log("sealed", request.dst, port, counter)
return routing.send(request.dst, port,
{enc = true, n = counter, d = toHex(sealed)}, request.srcPort)
end

local function finish(request, ok, err)
os.queueEvent("net_send_result", request.id, ok and true or false, err)
end




function netcrypt.send(dstAddress, dstPort, body, srcPort)
nextRequest = nextRequest + 1
local id = ("%d:%d"):format(os.getComputerID(), nextRequest)

os.queueEvent("net_send", id, dstAddress, dstPort, body, srcPort)

local timer = os.startTimer(SEND_TIMEOUT)
while true do
local event, p1, p2, p3 = os.pullEvent()
if event == "net_send_result" and p1 == id then
if p2 then return true end
return false, p3
elseif event == "timer" and p1 == timer then
return false, "timed out waiting for the crypto daemon"
end
end
end



function netcrypt.receive(port, timeout)
local timer = nil
local filter = nil
if timeout then
timer = os.startTimer(timeout)
else
filter = "net_data"
end

while true do
local event, p1, p2, p3, p4, p5, p6 = os.pullEvent(filter)
if event == "net_data" then
local src, sport, dport, body, encrypted, name = p1, p2, p3, p4, p5, p6
if port == nil or dport == port then
if timer then os.cancelTimer(timer) end
return {
src = src, sport = sport, dport = dport,
body = body, encrypted = encrypted, name = name,
}
end
elseif event == "timer" and p1 == timer then
return nil
end
end
end



local function handleInbound(packet)
local env = packet.body
if type(env) ~= "table" then return end

local port = packet.dport

if env.enc ~= true then


if netcrypt.isEncrypted(port) then
log("downgrade", packet.src, port)
return
end
os.queueEvent("net_data", packet.src, packet.sport, port, env.d, false)
return
end

local ciphertext = fromHex(env.d)
if not ciphertext then
log("malformed", packet.src, port)
return
end

local plaintext, err = peersession.open(packet.src, env.n, ciphertext)
if not plaintext then


log("rejected", packet.src, port, tostring(err))
return
end

local ok, body = pcall(textutils.unserialize, plaintext)
if not ok then
log("unserialize", packet.src, port)
return
end




os.queueEvent("net_data", packet.src, packet.sport, port, body, true,
peersession.nameOf(packet.src))
end

local function attempt(request)
local ok, err = deliver(request)
if ok then
finish(request, true)
return true
end
return false, err
end






local function inboundLoop()
while true do
local _, src, sport, dport, body = os.pullEvent("net_message")
handleInbound({src = src, sport = sport, dport = dport, body = body})
end
end

local function outboundLoop()
while true do
local event, p1, p2, p3, p4, p5 = os.pullEvent()

if event == "net_send" then
local request = {
id = p1, dst = p2, dstPort = p3, body = p4, srcPort = p5,
}

if not netcrypt.isEncrypted(request.dstPort)
or peersession.get(request.dst) then
local ok, err = attempt(request)
if not ok then finish(request, false, err) end
else



log("awaiting session", request.dst, request.dstPort)
pendingSends[request.dst] = pendingSends[request.dst] or {}
table.insert(pendingSends[request.dst], request)
os.queueEvent("peer_connect", request.dst)
end

elseif event == "peer_session" then
local address, established, detail = p1, p2, p3
local waiting = pendingSends[address]
pendingSends[address] = nil

for _, request in ipairs(waiting or {}) do
if established then
local ok, err = attempt(request)
if not ok then finish(request, false, err) end
else
finish(request, false, "no session: " .. tostring(detail))
end
end
end
end
end

function netcrypt.runtime()
if state.running then
error("netcrypt: daemon already running", 0)
end
state.running = true

local ok, err = pcall(parallel.waitForAny, inboundLoop, outboundLoop)

state.running = false
if not ok then error(err, 0) end
end

function netcrypt.isRunning()
return state.running == true
end

function netcrypt.shutdown()
state.running = false
pendingSends = {}
end

return netcrypt
]],
["netkeys.lua"] = [[







local x25519 = require("ccryptolib.x25519")
local ed25519 = require("ccryptolib.ed25519")
local random = require("ccryptolib.random")
local ip = require("ip")

local netkeys = {}

local DIR = "/net"
local F_STATIC = DIR .. "/static.key"
local F_SERVER = DIR .. "/server.key"
local F_SIGN = DIR .. "/sign.key"
local F_SIGNER = DIR .. "/signer.key"
local F_ALLOWED = DIR .. "/allowed"
local F_ADDRESSES = DIR .. "/addresses"
local F_ROLE = DIR .. "/role"
local F_SUBSTRATE = DIR .. "/substrate"
local F_PORTS = DIR .. "/ports"
local F_NAMES = DIR .. "/names"
local F_HOSTNAME = DIR .. "/hostname"
local F_INTERFACES = DIR .. "/interfaces"
local F_SUBNETS = DIR .. "/subnets"
local F_CHAIN = DIR .. "/chain"
local F_BAND = DIR .. "/band"




local ADDRESS_START = 100





local DEFAULT_NETWORK = 167772160
local DEFAULT_PREFIX = 24



local staticSk, staticPk
local signSk, signPk




local VOUCHER_CONTEXT = "acknet-voucher-v2"
local VOUCHER_TTL = 24 * 60 * 60
local NAME_LEN = 32
local VOUCHER_LEN = 8 + 8 + NAME_LEN + 32 + 64

function netkeys.toHex(s)
return (s:gsub(".", function(c) return ("%02x"):format(c:byte()) end))
end

function netkeys.fromHex(h)
if type(h) ~= "string" or #h % 2 ~= 0 or h:find("%X") then return nil end
return (h:gsub("%x%x", function(b) return string.char(tonumber(b, 16)) end))
end

local function readFile(path)
if not fs.exists(path) then return nil end
local f = fs.open(path, "r")
if not f then return nil end
local data = f.readAll()
f.close()
return data
end

local function writeFile(path, data)
if not fs.exists(DIR) then fs.makeDir(DIR) end
local f = fs.open(path, "w")
f.write(data)
f.close()
end



function netkeys.init()
if staticSk then return end

local stored = readFile(F_STATIC)
if stored then
staticSk = netkeys.fromHex((stored:gsub("%s", "")))
if not staticSk or #staticSk ~= 32 then
error("netkeys: " .. F_STATIC .. " is corrupt", 0)
end
else
if not random.isInit() then
error("netkeys: seed the RNG before generating a key", 0)
end
staticSk = random.random(32)
writeFile(F_STATIC, netkeys.toHex(staticSk))
end
staticPk = x25519.publicKey(staticSk)
end

function netkeys.publicKey()
netkeys.init()
return staticPk
end


function netkeys.exchange(peerPk)
netkeys.init()
return x25519.exchange(staticSk, peerPk)
end







local function u64le(n)
local b = {}
for i = 1, 8 do
b[i] = string.char(n % 256)
n = math.floor(n / 256)
end
return table.concat(b)
end

local function readU64le(s, at)
local n = 0
for i = 7, 0, -1 do
n = n * 256 + s:byte(at + i)
end
return n
end


function netkeys.initSigning()
if signSk then return end

local stored = readFile(F_SIGN)
if stored then
signSk = netkeys.fromHex((stored:gsub("%s", "")))
if not signSk or #signSk ~= 32 then
error("netkeys: " .. F_SIGN .. " is corrupt", 0)
end
else
if not random.isInit() then
error("netkeys: seed the RNG before generating a signing key", 0)
end
signSk = random.random(32)
writeFile(F_SIGN, netkeys.toHex(signSk))
end
signPk = ed25519.publicKey(signSk)
end

function netkeys.signingKey()
netkeys.initSigning()
return signPk
end









function netkeys.sign(context, data)
if type(context) ~= "string" or context == "" then
error("netkeys.sign: a context string is required", 2)
end
netkeys.initSigning()
return ed25519.sign(signSk, signPk, context .. data)
end











function netkeys.signerKey()
local h = readFile(F_SIGNER)
if h then
local pk = netkeys.fromHex((h:gsub("%s", "")))
if pk and #pk == 32 then return pk end
return nil
end

if netkeys.isServer() then return netkeys.signingKey() end
return nil
end

function netkeys.setSignerKey(hex)
local pk = netkeys.fromHex(hex)
if not pk or #pk ~= 32 then
error("netkeys.setSignerKey: expected 64 hex characters", 2)
end
writeFile(F_SIGNER, hex)
end

local NUL = string.char(0)

local function padName(name)
name = name or ""
if #name > NAME_LEN then
error(("netkeys: name longer than %d characters"):format(NAME_LEN), 0)
end
return name .. string.rep(NUL, NAME_LEN - #name)
end

local function unpadName(field)
local stop = field:find(NUL, 1, true)
return stop and field:sub(1, stop - 1) or field
end







function netkeys.issueVoucher(address, peerPk, name, ttl)
netkeys.initSigning()

local network, prefix = netkeys.authority()
if not ip.contains(network, prefix, address) then
return nil, ("%s is outside our grant of %s"):format(
ip.format(address), ip.formatCidr(network, prefix))
end

local expires = os.epoch("utc") + (ttl or VOUCHER_TTL) * 1000
local body = u64le(address) .. u64le(expires) .. padName(name) .. peerPk
return body .. ed25519.sign(signSk, signPk, VOUCHER_CONTEXT .. body)
end



















local CERT_CONTEXT = "acknet-delegation-v1"
local CERT_TTL = 24 * 60 * 60
local CERT_LEN = 8 + 8 + 8 + NAME_LEN + 32 + 64




local MAX_CHAIN = 8




local function parseCert(cert)
if type(cert) ~= "string" or #cert ~= CERT_LEN then return nil end
local body = cert:sub(1, CERT_LEN - 64)
return {
network = readU64le(body, 1),
prefix = readU64le(body, 9),
expires = readU64le(body, 17),
name = unpadName(body:sub(25, 24 + NAME_LEN)),
signer = body:sub(25 + NAME_LEN),
}
end

netkeys.parseCert = parseCert

local function openCert(cert, byPk)
local fields = parseCert(cert)
if not fields then return nil, "malformed certificate" end

local body = cert:sub(1, CERT_LEN - 64)
local sig = cert:sub(CERT_LEN - 63)
if not ed25519.verify(byPk, CERT_CONTEXT .. body, sig) then
return nil, "bad certificate signature"
end
if os.epoch("utc") > fields.expires then return nil, "certificate expired" end

return fields
end


function netkeys.chain()
local out = {}
local data = readFile(F_CHAIN)
if not data then return out end
for line in data:gmatch("[^\r\n]+") do
local cert = netkeys.fromHex((line:gsub("%s", "")))
if cert and #cert == CERT_LEN then out[#out + 1] = cert end
end
return out
end




function netkeys.decodeChain(hexList)
if hexList == nil then return nil end
if type(hexList) ~= "table" then return {} end

local out = {}
for _, hex in ipairs(hexList) do
local cert = netkeys.fromHex(type(hex) == "string" and hex or "")
out[#out + 1] = cert or ""
end
return out
end

function netkeys.chainHex()
local out = {}
for _, cert in ipairs(netkeys.chain()) do out[#out + 1] = netkeys.toHex(cert) end
return out
end

function netkeys.setChain(hexList)
local lines = {}
for _, hex in ipairs(hexList or {}) do lines[#lines + 1] = hex end
writeFile(F_CHAIN, table.concat(lines, "\n"))
end




function netkeys.authority()
local chain = netkeys.chain()
if #chain == 0 then return 0, 0 end

local ours = parseCert(chain[1])
if not ours then return 0, 0 end
return ours.network, ours.prefix
end

function netkeys.issueCert(signerPk, network, prefix, name, ttl)
netkeys.initSigning()

if type(signerPk) ~= "string" or #signerPk ~= 32 then
return nil, "expected a 32-byte signing key"
end

local ourNetwork, ourPrefix = netkeys.authority()
if not ip.within(network, prefix, ourNetwork, ourPrefix) then
return nil, ("%s is outside our own grant of %s"):format(
ip.formatCidr(network, prefix),
ip.formatCidr(ourNetwork, ourPrefix))
end

local expires = os.epoch("utc") + (ttl or CERT_TTL) * 1000
local body = u64le(ip.network(network, prefix)) .. u64le(prefix)
.. u64le(expires) .. padName(name) .. signerPk
return body .. ed25519.sign(signSk, signPk, CERT_CONTEXT .. body)
end













local function qualify(label, zone)
if zone == "" then return label end
if label == "" then return zone end
return label .. "." .. zone
end

netkeys.qualify = qualify


local function descend(zone, label)
if label == "" then return zone end
return qualify(label, zone)
end







function netkeys.verifyVoucher(voucher, chain)
local anchor = netkeys.signerKey()
if not anchor then return nil, "no pinned signer key" end
if type(voucher) ~= "string" or #voucher ~= VOUCHER_LEN then
return nil, "malformed voucher"
end


local signer = anchor
local network, prefix = 0, 0
local zone = ""

if chain ~= nil then
if type(chain) ~= "table" then return nil, "malformed chain" end
if #chain > MAX_CHAIN then return nil, "certificate chain too long" end

for i = #chain, 1, -1 do
local cert, why = openCert(chain[i], signer)
if not cert then return nil, why end

if not ip.within(cert.network, cert.prefix, network, prefix) then
return nil, ("delegation of %s exceeds a grant of %s"):format(
ip.formatCidr(cert.network, cert.prefix),
ip.formatCidr(network, prefix))
end

signer, network, prefix = cert.signer, cert.network, cert.prefix


zone = descend(zone, cert.name)
end
end

local body = voucher:sub(1, VOUCHER_LEN - 64)
local sig = voucher:sub(VOUCHER_LEN - 63)

if not ed25519.verify(signer, VOUCHER_CONTEXT .. body, sig) then
return nil, "bad signature"
end

local expires = readU64le(body, 9)
if os.epoch("utc") > expires then return nil, "voucher expired" end

local address = readU64le(body, 1)




if not ip.contains(network, prefix, address) then
return nil, ("%s is outside the signer's grant of %s"):format(
ip.format(address), ip.formatCidr(network, prefix))
end

return address,
body:sub(17 + NAME_LEN),
qualify(unpadName(body:sub(17, 16 + NAME_LEN)), zone)
end






local function readNames()
local data = readFile(F_NAMES)
if not data then return {} end
local ok, t = pcall(textutils.unserialize, data)
if ok and type(t) == "table" then return t end
return {}
end

function netkeys.names()
return readNames()
end

function netkeys.nameFor(pk)
return readNames()[netkeys.toHex(pk)]
end

function netkeys.setName(hex, name)
if type(name) ~= "string" or name == "" or #name > NAME_LEN then
error(("netkeys.setName: name must be 1-%d characters"):format(NAME_LEN), 2)
end
if name:find(NUL, 1, true) then
error("netkeys.setName: name cannot contain a null byte", 2)
end



if name:find(".", 1, true) then
error("netkeys.setName: a name cannot contain '.'", 2)
end

local names = readNames()
for owner, taken in pairs(names) do
if taken == name and owner ~= hex then
error(("netkeys.setName: '%s' already belongs to %s"):format(
name, owner:sub(1, 16)), 2)
end
end

names[hex] = name
writeFile(F_NAMES, textutils.serialize(names))
end



function netkeys.zone()
local zone = ""
local chain = netkeys.chain()

for i = #chain, 1, -1 do
local cert = parseCert(chain[i])
if not cert then return zone end
zone = descend(zone, cert.name)
end
return zone
end





function netkeys.hostname()
local h = readFile(F_HOSTNAME)
return h and (h:gsub("%s", "")) or nil
end

function netkeys.setHostname(name)
if type(name) ~= "string" or name == "" or #name > NAME_LEN then
error(("netkeys.setHostname: name must be 1-%d characters"):format(NAME_LEN), 2)
end
if name:find("%s") then
error("netkeys.setHostname: name cannot contain spaces", 2)
end
writeFile(F_HOSTNAME, name)
end









function netkeys.assignName(hex, preferred)
if type(preferred) ~= "string" or preferred == "" then
return nil, "no name requested"
end

local names = readNames()



if names[hex] then return names[hex] end

local taken = {}
for owner, name in pairs(names) do
if owner ~= hex then taken[name] = true end
end

if #preferred <= NAME_LEN and not taken[preferred] then
netkeys.setName(hex, preferred)
return preferred
end

for n = 1, 999 do
local suffix = tostring(n)

local candidate = preferred:sub(1, NAME_LEN - #suffix) .. suffix
if not taken[candidate] then
netkeys.setName(hex, candidate)
return candidate
end
end

return nil, ("no free variant of '%s'"):format(preferred)
end

function netkeys.keyForName(name)
for hex, assigned in pairs(readNames()) do
if assigned == name then return hex end
end
return nil
end

function netkeys.role()
local r = readFile(F_ROLE)
return r and (r:gsub("%s", "")) or nil
end



function netkeys.isServer()
local r = netkeys.role()
return r == "server" or r == "both"
end

function netkeys.isClient()
local r = netkeys.role()
return r == "client" or r == "both"
end



function netkeys.substrate()
local s = readFile(F_SUBSTRATE)
return s and (s:gsub("%s", "")) or "rednet"
end

function netkeys.setSubstrate(name)
if name ~= "rednet" and name ~= "hopnet" then
error("netkeys.setSubstrate: expected 'rednet' or 'hopnet'", 2)
end
writeFile(F_SUBSTRATE, name)
end




function netkeys.encryptedPorts()
local set = {}
local data = readFile(F_PORTS)
if not data then return set end
for line in data:gmatch("[^\r\n]+") do
local port = tonumber((line:gsub("%s", "")))
if port then set[port] = true end
end
return set
end

function netkeys.setPortEncrypted(port, enabled)
local set = netkeys.encryptedPorts()
set[port] = enabled and true or nil

local ports = {}
for value in pairs(set) do ports[#ports + 1] = value end
table.sort(ports)

local lines = {}
for _, value in ipairs(ports) do lines[#lines + 1] = tostring(value) end
writeFile(F_PORTS, table.concat(lines, "\n"))
end

function netkeys.setRole(role)
if role ~= "server" and role ~= "client" and role ~= "both" then
error("netkeys.setRole: role must be 'server', 'client' or 'both'", 2)
end
writeFile(F_ROLE, role)
end



function netkeys.serverKey()
local h = readFile(F_SERVER)
if not h then return nil end
local pk = netkeys.fromHex((h:gsub("%s", "")))
if not pk or #pk ~= 32 then return nil end
return pk
end

function netkeys.setServerKey(hex)
local pk = netkeys.fromHex(hex)
if not pk or #pk ~= 32 then
error("netkeys.setServerKey: expected 64 hex characters", 2)
end
writeFile(F_SERVER, hex)
end


local function readAllowed()
local set = {}
local data = readFile(F_ALLOWED)
if not data then return set end
for line in data:gmatch("[^\r\n]+") do
local hex = line:gsub("%s", "")
if #hex == 64 then set[hex] = true end
end
return set
end

function netkeys.allowed()
return readAllowed()
end

function netkeys.isAllowed(pk)
return readAllowed()[netkeys.toHex(pk)] == true
end

function netkeys.allow(hex)
local pk = netkeys.fromHex(hex)
if not pk or #pk ~= 32 then
error("netkeys.allow: expected 64 hex characters", 2)
end
local set = readAllowed()
set[hex] = true
local lines = {}
for k in pairs(set) do lines[#lines + 1] = k end
table.sort(lines)
writeFile(F_ALLOWED, table.concat(lines, "\n"))
end

function netkeys.revoke(hex)
local set = readAllowed()
set[hex] = nil
local lines = {}
for k in pairs(set) do lines[#lines + 1] = k end
table.sort(lines)
writeFile(F_ALLOWED, table.concat(lines, "\n"))
end













local function readLines(path)
local out = {}
local data = readFile(path)
if not data then return out end
for line in data:gmatch("[^\r\n]+") do
local trimmed = line:match("^%s*(.-)%s*$")
if trimmed ~= "" and not trimmed:match("^#") then out[#out + 1] = trimmed end
end
return out
end



function netkeys.interfaces()
local out = {}
for _, line in ipairs(readLines(F_INTERFACES)) do
local cidr, modem = line:match("^(%S+)%s*(%S*)$")
local addr, prefix = ip.parseCidr(cidr or "")
if addr then
out[#out + 1] = {
address = addr,
prefix = prefix,
modem = modem ~= "" and modem or nil,
}
end
end
return out
end

local function writeInterfaces(list)
local lines = {}
for _, iface in ipairs(list) do
lines[#lines + 1] = ip.formatCidr(iface.address, iface.prefix)
.. (iface.modem and (" " .. iface.modem) or "")
end
writeFile(F_INTERFACES, table.concat(lines, "\n"))
end

function netkeys.addInterface(address, prefix, modem)
local list = netkeys.interfaces()
for i, iface in ipairs(list) do


if iface.address == address then
table.remove(list, i)
break
end
end
list[#list + 1] = {address = address, prefix = prefix, modem = modem}
writeInterfaces(list)
end

function netkeys.removeInterface(address)
local list, kept = netkeys.interfaces(), {}
for _, iface in ipairs(list) do
if iface.address ~= address then kept[#kept + 1] = iface end
end
writeInterfaces(kept)
return #kept < #list
end




function netkeys.serverInterfaces()
local list = netkeys.interfaces()
if #list > 0 then return list end
return {{address = DEFAULT_NETWORK + 1, prefix = DEFAULT_PREFIX, modem = nil}}
end



function netkeys.subnets()
local out = {}
for _, line in ipairs(readLines(F_SUBNETS)) do



local bandBase, bandSize = line:match("band%s+(%d+)%s+(%d+)%s*$")
local head = line:gsub("%s*band%s+%d+%s+%d+%s*$", "")

local cidr, via = head:match("^(%S+)%s+via%s+(%S+)$")
if not cidr then cidr = head:match("^(%S+)$") end

local network, prefix = ip.parseCidr(cidr or "")
if network then
out[#out + 1] = {
network = ip.network(network, prefix),
prefix = prefix,
via = via and ip.parse(via) or nil,
band = bandBase and
{base = tonumber(bandBase), size = tonumber(bandSize)} or nil,
}
end
end

if #out == 0 then
out[1] = {network = DEFAULT_NETWORK, prefix = DEFAULT_PREFIX}
end
return out
end

local function writeSubnets(list)
local lines = {}
for _, subnet in ipairs(list) do
lines[#lines + 1] = ip.formatCidr(subnet.network, subnet.prefix)
.. (subnet.via and (" via " .. ip.format(subnet.via)) or "")
.. (subnet.band and
(" band " .. subnet.band.base .. " " .. subnet.band.size) or "")
end
writeFile(F_SUBNETS, table.concat(lines, "\n"))
end

function netkeys.setSubnet(network, prefix, via, subnetBand)
network = ip.network(network, prefix)

local list = {}
for _, subnet in ipairs(netkeys.subnets()) do
if not (subnet.network == network and subnet.prefix == prefix) then
list[#list + 1] = subnet
end
end
list[#list + 1] = {network = network, prefix = prefix, via = via,
band = subnetBand}
writeSubnets(list)
end




function netkeys.band()
local text = readFile(F_BAND)
if not text then return nil end
local base, size = text:match("(%d+)%s+(%d+)")
if not base then return nil end
return {base = tonumber(base), size = tonumber(size)}
end

function netkeys.setBand(b)
if not b then
if fs.exists(F_BAND) then fs.delete(F_BAND) end
return
end
writeFile(F_BAND, b.base .. " " .. b.size)
end

function netkeys.removeSubnet(network, prefix)
network = ip.network(network, prefix)

local list, kept = netkeys.subnets(), {}
for _, subnet in ipairs(list) do
if not (subnet.network == network and subnet.prefix == prefix) then
kept[#kept + 1] = subnet
end
end
writeSubnets(kept)
return #kept < #list
end







local function readAddresses()
local data = readFile(F_ADDRESSES)
if not data then return {} end
local ok, t = pcall(textutils.unserialize, data)
if ok and type(t) == "table" then return t end
return {}
end


function netkeys.addresses()
local out = {}
for hex, dotted in pairs(readAddresses()) do
local addr = type(dotted) == "string" and ip.parse(dotted) or nil
if addr then out[hex] = addr end
end
return out
end

local function storeAddress(hex, address)
local book = readAddresses()
book[hex] = ip.format(address)
writeFile(F_ADDRESSES, textutils.serialize(book))
end



function netkeys.setAddress(hex, address)
storeAddress(hex, address)
end






function netkeys.addressFor(pk, network, prefix)
local hex = netkeys.toHex(pk)
local book = netkeys.addresses()

local existing = book[hex]
if existing and ip.contains(network, prefix, existing) then return existing end

local base = ip.network(network, prefix)
local last = ip.broadcastOf(network, prefix)

local taken = {}
for _, addr in pairs(book) do taken[addr] = true end



for candidate = base + ADDRESS_START, last - 1 do
if not taken[candidate] then
storeAddress(hex, candidate)
return candidate
end
end

return nil, ("no free address in %s"):format(ip.formatCidr(base, prefix))
end

return netkeys
]],
["netrecv.lua"] = [[







local net = require("net")
local netcrypt = require("netcrypt")
local routing = require("routing")

local args = {...}
local target = args[1]

if not target then
local names = {}
for name in pairs(net.services()) do names[#names + 1] = name end
table.sort(names)

print("usage: netrecv <service|port>")
print("services: " .. (#names > 0 and table.concat(names, " ") or "none"))
return
end

if not net.ready() then
printError("network is not up")
return
end



local service = not tonumber(target) and target or nil
local port, ok, err

if service then
ok, err = net.serve(service)
port = net.port(service)
else
port = tonumber(target)
ok, err = routing.bind(port)
end

if not ok then
printError(tostring(err))
return
end

local sealed = service and net.isEncrypted(service) or netcrypt.isEncrypted(port)
print(("%s %s %s"):format(net.whoami(), target, sealed and "sealed" or "plain"))

local function listen()
while true do
local packet = service and net.receive(service) or netcrypt.receive(port)


local who = packet.from or packet.name
or (type(packet.src) == "number" and net.formatAddress(packet.src))
or tostring(packet.src)
print(("%s%s> %s"):format(
packet.encrypted and "*" or "", who, tostring(packet.body)))
end
end

local held, failure = pcall(listen)
routing.unbind(port)

if not held then error(failure, 0) end
]],
["netsend.lua"] = [[






local net = require("net")
local netcrypt = require("netcrypt")

local args = {...}
local peer = args[1]
local target = args[2]

if not peer or not target then
local names = {}
for name in pairs(net.services()) do names[#names + 1] = name end
table.sort(names)

print("usage: netsend <address|hostname> <service|port> <message...>")
print("services: " .. (#names > 0 and table.concat(names, " ") or "none"))
return
end

if not net.ready() then
printError("network is not up")
return
end

local body = table.concat(args, " ", 3)

local port = tonumber(target)
local sealed
if port then
sealed = netcrypt.isEncrypted(port)
else
port = net.port(target)
if not port then
printError(("unknown service: %s"):format(target))
return
end
sealed = net.isEncrypted(target)
end


local dotted, err = net.resolve(peer)
if not dotted then
printError(("%s: %s"):format(tostring(peer), tostring(err)))
return
end
local address = net.parseAddress(dotted)

local ok
ok, err = netcrypt.send(address, port, body, port)
if not ok then
printError(tostring(err))
return
end



print(("-> %s (%s) %s %s"):format(
tostring(peer), dotted, target, sealed and "sealed" or "plain"))
]],
["netsession.lua"] = [[











local acknet = require("acknet")
local netkeys = require("netkeys")
local handshake = require("handshake")
local ip = require("ip")

local netsession = {}

local PROTOCOL = "acknet_hs"
local HOSTNAME = "server"
local RESEND = 3
local ATTEMPTS = 5
local PENDING_TTL = 60



local pending = {}
local sessions = {}















local allocator = nil

function netsession.setAllocator(fn)
allocator = fn
end

local function frame(peer, t, ephHex, data)
acknet.send(peer, {t = t, e = ephHex, d = netkeys.toHex(data)}, PROTOCOL)
end

local function sweep()
local now = os.epoch("utc")
for k, p in pairs(pending) do
if now > p.expires then pending[k] = nil end
end
end

local function handleMsg1(ourPk, sender, ephHex, msg1)
local p = pending[ephHex]
if p then


frame(sender, 2, ephHex, p.msg2)
return
end

local st = handshake.startResponder(ourPk)
if not handshake.responderReadMsg1(st, msg1, netkeys.exchange) then
return "message 1 failed authentication"
end

local msg2 = handshake.responderWriteMsg2(st, "")
pending[ephHex] = {
st = st,
msg2 = msg2,
sender = sender,
expires = os.epoch("utc") + PENDING_TTL * 1000,
}
frame(sender, 2, ephHex, msg2)
end




local function handleMsg3(sender, ephHex, msg3, relay)
local p = pending[ephHex]
if not p then return "message 3 for an unknown session" end


if p.reply then
frame(sender, 4, ephHex, p.reply)
return
end

local clientPk, offered, tx, rx = handshake.responderReadMsg3(p.st, msg3)
if not clientPk then
pending[ephHex] = nil
return "message 3 failed authentication"
end

local clientHex = netkeys.toHex(clientPk)
local reply



if netkeys.isAllowed(clientPk) then



local signingKey = nil
if type(offered) == "string" and #offered == 32 then signingKey = offered end

local plan, why
if allocator then
plan, why = allocator(clientPk, relay or sender, signingKey)
end

if not plan then
why = why or "the server has no address to give"
reply = handshake.seal(tx, 0,
textutils.serialize({ok = false, reason = why}))
print(("refused %s (%s)"):format(clientHex:sub(1, 16), tostring(why)))
else
sessions[clientHex] = {
address = plan.address, tx = tx, rx = rx,
counter = 1,





peerAddress = (not relay) and sender or nil,

link = (not relay) and handshake.linkSecret(rx, tx) or nil,
}
os.queueEvent("net_link_changed")




local voucher, voucherErr = netkeys.issueVoucher(
plan.address, clientPk, netkeys.nameFor(clientPk))

if not voucher then
reply = handshake.seal(tx, 0, textutils.serialize(
{ok = false, reason = tostring(voucherErr)}))
print(("refused %s (%s)"):format(
clientHex:sub(1, 16), tostring(voucherErr)))
else
reply = handshake.seal(tx, 0, textutils.serialize({
ok = true,
address = plan.address,
prefix = plan.prefix,
gateway = plan.gateway,
routes = plan.routes,




band = plan.band,
voucher = netkeys.toHex(voucher),


cert = plan.cert,
chain = plan.chain,


relayed = relay ~= nil,
}))
print(("admitted %s as %s%s"):format(
clientHex:sub(1, 16), ip.format(plan.address),
plan.cert and "  (delegated)" or ""))
end
end
else
reply = handshake.seal(tx, 0,
textutils.serialize({ok = false, reason = "not on the allowlist"}))
print(("refused %s (not allowed)"):format(clientHex:sub(1, 16)))
end


p.reply = reply
p.expires = os.epoch("utc") + PENDING_TTL * 1000
frame(sender, 4, ephHex, reply)
end

function netsession.serve()
netkeys.init()
netkeys.initSigning()
local ourPk = netkeys.publicKey()




acknet.host(PROTOCOL, HOSTNAME)

print("handshake server listening")
print("exchange key: " .. netkeys.toHex(ourPk))
print("signer key:   " .. netkeys.toHex(netkeys.signingKey()))

while true do
local packet = acknet.receive(PROTOCOL)
sweep()

local body = packet.body
if type(body) == "table" and type(body.d) == "string"
and type(body.e) == "string" then
local data = netkeys.fromHex(body.d)
local err
if data and body.t == 1 then
err = handleMsg1(ourPk, packet.sender_id, body.e, data)
elseif data and body.t == 3 then
err = handleMsg3(packet.sender_id, body.e, data,
type(body.r) == "number" and body.r or nil)
end
if err then
print(("from %d: %s"):format(packet.sender_id, err))
end
end
end
end

function netsession.sessions()
return sessions
end




local clientSession = nil




function netsession.linkSecrets()
local map = {}

if clientSession and clientSession.link then
map[clientSession.serverAddress] = clientSession.link
end


for _, session in pairs(sessions) do
if session.link and session.peerAddress then
map[session.peerAddress] = session.link
end
end
return map
end



local function request(peer, t, ephHex, data, expect)
for _ = 1, ATTEMPTS do
frame(peer, t, ephHex, data)



local deadline = os.epoch("utc") + RESEND * 1000
while true do
local remaining = (deadline - os.epoch("utc")) / 1000
if remaining <= 0 then break end

local packet = acknet.receive(PROTOCOL, remaining)
if packet and packet.sender_id == peer
and type(packet.body) == "table"
and packet.body.t == expect
and packet.body.e == ephHex then
return netkeys.fromHex(packet.body.d)
end
end
end
return nil
end


function netsession.connect(serverAddress)
netkeys.init()

local serverPk = netkeys.serverKey()
if not serverPk then
return nil, "no pinned server key -- run 'netadmin pin <hex>'"
end

local st, msg1 = handshake.startInitiator(serverPk, "")
local ephHex = netkeys.toHex(msg1:sub(1, 32))

local msg2 = request(serverAddress, 1, ephHex, msg1, 2)
if not msg2 then return nil, "no reply to message 1" end

if not handshake.initiatorReadMsg2(st, msg2) then


return nil, "message 2 failed authentication -- wrong server key?"
end




local offer = ""
if netkeys.isServer() then offer = netkeys.signingKey() end

local msg3, tx, rx = handshake.initiatorFinish(
st, netkeys.publicKey(), netkeys.exchange, offer)

local msg4 = request(serverAddress, 3, ephHex, msg3, 4)
if not msg4 then return nil, "no reply to message 3" end

local plain = handshake.open(rx, 0, msg4)
if not plain then return nil, "welcome failed authentication" end

local ok, welcome = pcall(textutils.unserialize, plain)
if not ok or type(welcome) ~= "table" then
return nil, "welcome was malformed"
end
if not welcome.ok then
return nil, welcome.reason or "refused by server"
end

clientSession = {
serverAddress = serverAddress,


relayed = welcome.relayed == true,
address = welcome.address,


prefix = welcome.prefix,
gateway = welcome.gateway,
routes = welcome.routes,


band = welcome.band,

link = (welcome.relayed ~= true) and handshake.linkSecret(tx, rx) or nil,


voucher = welcome.voucher,


cert = welcome.cert,
chain = welcome.chain,
tx = tx,
rx = rx,
counter = 1,
}
os.queueEvent("net_link_changed")
return clientSession
end






function netsession.findServer()
return acknet.lookup(PROTOCOL, HOSTNAME, true)
end

return netsession
]],
["netstart.lua"] = [[








local acknet = require("acknet")
local random = require("ccryptolib.random")
local netkeys = require("netkeys")
local netsession = require("netsession")
local peersession = require("peersession")
local routing = require("routing")
local netcrypt = require("netcrypt")
local ipnet = require("ipnet")
local ip = require("ip")
local bootrelay = require("bootrelay")
local icmp = require("icmp")
local band = require("band")

local args = {...}




local serverArg = nil
if args[1] then
serverArg = ip.parse(args[1])
local id = tonumber(args[1])
if not serverArg and id and id >= 0 and id < 65536 and id == math.floor(id) then
serverArg = ip.linkLocal(id)
end
if not serverArg then
printError(("'%s' is not an address or a computer id"):format(args[1]))
return
end
end


if not random.isInit() then
write("seeding crypto rng... ")
random.initWithTiming()
print("done")
end

netkeys.init()

local role = netkeys.role()
if not role then
printError("this computer has no role yet")
print("run 'netadmin role server', 'client', or 'both'")
return
end



local isServer = netkeys.isServer()
local isClient = netkeys.isClient()











local zoneCache = nil

local function ourZone()
if zoneCache == nil then zoneCache = netkeys.zone() end
return zoneCache
end

local function forgetZone()
zoneCache = nil
end

local function ourName()
local zone = ourZone()
return zone ~= "" and zone or (netkeys.hostname() or "server")
end




local function ownLabel()
return ourZone() ~= "" and "" or ourName()
end




local substrateName = netkeys.substrate()
local link = substrateName == "hopnet" and require("hopnet") or require("rednetsub")




ipnet.setSubstrate(link)
acknet.setSubstrate(ipnet)
if not ipnet.init() then
printError("no modem found")
return
end





local declared = isServer and netkeys.serverInterfaces()
or netkeys.interfaces()




local ownBand = netkeys.band()
if ownBand then
for _, iface in ipairs(declared) do
for _, subnet in ipairs(netkeys.subnets()) do
if not subnet.via and subnet.band
and ip.contains(subnet.network, subnet.prefix, iface.address) then
iface.band = subnet.band
end
end
iface.band = iface.band or ownBand
end
end

ipnet.setInterfaces(declared)
if ownBand and #declared == 0 then

ipnet.setBands({}, ownBand)
end





ipnet.setForwarding(isServer or #declared > 0)



local policy = netkeys.encryptedPorts()
netcrypt.setPolicy(policy)

local encryptedPorts = {}
for port in pairs(policy) do encryptedPorts[#encryptedPorts + 1] = port end
table.sort(encryptedPorts)

print(("role: %s   key: %s"):format(role, netkeys.toHex(netkeys.publicKey()):sub(1, 16)))
if #encryptedPorts > 0 then
print("encrypted ports: " .. table.concat(encryptedPorts, " "))
end
print("substrate: " .. substrateName)
if ownBand then print("band: " .. band.format(ownBand)) end
if #declared > 0 then
for _, iface in ipairs(declared) do
print(("  %s %s"):format(
ip.formatCidr(iface.address, iface.prefix), iface.modem or "(all)"))
end
else
print("  " .. ip.format(ipnet.localAddress()) .. " (link-local, unassigned)")
end








local function ownVoucher()
local voucher, why = netkeys.issueVoucher(
ipnet.localAddress(), netkeys.publicKey(), ownLabel())
if not voucher then
printError("cannot vouch for ourselves: " .. tostring(why))
print("list this computer's OWN subnet address first in /net/interfaces")
return nil
end
return netkeys.toHex(voucher)
end

local JOIN_RETRY = 5
local JOIN_RETRY_MAX = 60

local function clientTask()



local delay = JOIN_RETRY
local session



while not session do
local serverAddress = serverArg
if not serverAddress then
serverAddress = netsession.findServer()
end

if serverAddress then
print("handshaking with " .. ip.format(serverAddress) .. "...")
local err
session, err = netsession.connect(serverAddress)
if not session then
printError("handshake failed: " .. tostring(err))
end
else
print("no handshake server answered")
end

if not session then
print(("retrying in %ds -- ctrl+t to stop"):format(delay))


os.sleep(delay)
delay = math.min(delay * 2, JOIN_RETRY_MAX)
end
end

print("admitted as " .. ip.format(session.address))




if not session.prefix then
printError("the server sent no subnet -- assuming /24")
end
ipnet.configure(session.address, session.prefix or 24, session.gateway,
session.band)
ipnet.setRoutes(session.routes)





if #declared > 0 then
local matches = false
for _, iface in ipairs(declared) do
if iface.address == session.address then matches = true end
end
if not matches then
printError(("the server assigned %s, which is not in /net/interfaces")
:format(ip.format(session.address)))
print("pin it with 'netadmin address' on the server, or fix it here")
end
end

if session.gateway then
print("gateway: " .. ip.format(session.gateway))
end
for _, route in ipairs(session.routes or {}) do
print(("route: %s via %s"):format(
ip.formatCidr(route.network, route.prefix), ip.format(route.via)))
end









routing.setParent(session.gateway or session.serverAddress)





if not routing.address() then
routing.setLocal(session.address)
end









if session.voucher and not isServer then
peersession.setVoucher(session.voucher)



peersession.setChain(session.chain)



local voucher = netkeys.fromHex(session.voucher)
local assigned = nil
if voucher then
local _, _, name = netkeys.verifyVoucher(
voucher, netkeys.decodeChain(session.chain))
assigned = name ~= "" and name or nil
end
if assigned then
routing.setName(assigned)
print("hostname: " .. assigned)
end

elseif session.voucher then
print("joined as " .. ip.format(session.address)
.. "; keeping our own name and voucher")





if session.cert then
local chain = {session.cert}
for _, hex in ipairs(session.chain or {}) do
chain[#chain + 1] = hex
end
netkeys.setChain(chain)

forgetZone()
routing.setName(ourName())

local granted = netkeys.parseCert(netkeys.fromHex(session.cert))
if granted then
print(("delegated %s"):format(
ip.formatCidr(granted.network, granted.prefix)))
end

peersession.setVoucher(ownVoucher())
peersession.setChain(netkeys.chainHex())
else
printError("no delegation issued -- this computer cannot sign")
print("add a 'subnet <cidr> via " .. ip.format(session.address)
.. "' on the parent")
end

else
printError("no voucher issued -- peer sessions will not work")
print("the server may predate voucher support; restart it")
end



while true do os.pullEvent() end
end







local function withinZone(name)
local zone = ourZone()
if zone == "" then return name end
if name == zone then return "" end

local suffix = "." .. zone
if #name > #suffix and name:sub(-#suffix) == suffix then
return name:sub(1, #name - #suffix)
end
return nil
end

local function directoryResolver(query)



local relative = query.name and withinZone(query.name) or nil

if (query.address ~= nil and ipnet.isOurs(query.address))
or (query.name ~= nil and (relative == "" or query.name == ourName())) then
return {
address = ipnet.localAddress(),
voucher = ownVoucher(),
chain = netkeys.chainHex(),
}
end



if query.name ~= nil and relative == nil then return nil end




if relative ~= nil and relative:find(".", 1, true) then
local delegate = relative:match("([^.]+)$")
local hex = delegate and netkeys.keyForName(delegate) or nil
local addr = hex and netkeys.addresses()[hex] or nil
if addr then return nil, addr end
return nil
end


local wanted = relative and netkeys.keyForName(relative) or nil

local live = netsession.sessions()
for hex, addr in pairs(netkeys.addresses()) do
local matches = (wanted and hex == wanted) or
(not wanted and addr == query.address)

if matches then
local session = live[hex]
if not session then return nil end




local pk = netkeys.fromHex(hex)
local voucher = netkeys.issueVoucher(addr, pk, netkeys.nameFor(pk))
if not voucher then return nil end

return {
address = addr,
voucher = netkeys.toHex(voucher),


chain = netkeys.chainHex(),
}
end
end




if query.address then
for _, subnet in ipairs(netkeys.subnets()) do
if subnet.via
and ip.contains(subnet.network, subnet.prefix, query.address) then
return nil, subnet.via
end
end
end

return nil
end








local function segmentFor(cameFrom)
if cameFrom ~= nil and not ip.isLinkLocal(cameFrom) then
for _, subnet in ipairs(netkeys.subnets()) do
if ip.contains(subnet.network, subnet.prefix, cameFrom) then
return {address = cameFrom, prefix = subnet.prefix}
end
end
return nil
end

local modem = ipnet.ingressOf(cameFrom)
local ifaces = ipnet.interfaces()

for _, iface in ipairs(ifaces) do
if iface.modem == modem then return iface end
end



return ifaces[1]
end





local function routesFor(iface)
local routes = {}
for _, subnet in ipairs(netkeys.subnets()) do
if subnet.via
and not ip.contains(iface.address, iface.prefix, subnet.network)
and ip.contains(iface.address, iface.prefix, subnet.via) then
routes[#routes + 1] = {
network = subnet.network,
prefix = subnet.prefix,
via = subnet.via,
}
end
end
return routes
end








local function delegationFor(address, signingKey, name)
if not signingKey then return nil end

for _, subnet in ipairs(netkeys.subnets()) do
if subnet.via == address then
local cert, why = netkeys.issueCert(
signingKey, subnet.network, subnet.prefix, name)
if cert then return netkeys.toHex(cert) end

printError(("cannot delegate %s: %s"):format(
ip.formatCidr(subnet.network, subnet.prefix), tostring(why)))
return nil
end
end
return nil
end

local function allocate(clientPk, cameFrom, signingKey)
local segment = segmentFor(cameFrom)
if not segment then
return nil, ("no subnet covers %s"):format(ip.format(cameFrom))
end

local address, err = netkeys.addressFor(clientPk, segment.address, segment.prefix)
if not address then return nil, err end

local plan = {
address = address,
prefix = segment.prefix,


gateway = segment.address,
routes = routesFor(segment),
}





plan.chain = netkeys.chainHex()
plan.cert = delegationFor(address, signingKey, netkeys.nameFor(clientPk))





plan.band = segment.band or netkeys.band()
for _, subnet in ipairs(netkeys.subnets()) do
if subnet.band and ip.contains(subnet.network, subnet.prefix, address) then
plan.band = subnet.band
end
end

return plan
end


local function ownRoutes()
local routes = {}
for _, subnet in ipairs(netkeys.subnets()) do
if subnet.via then
routes[#routes + 1] = {
network = subnet.network,
prefix = subnet.prefix,
via = subnet.via,
}
end
end
return routes
end





local services = {}









local function linkSecrets()
local map = {}

local function add(source)
for address, secret in pairs(source) do
local neighbour = ipnet.linkFor(address)
if neighbour then map[neighbour] = secret end
end
end

add(peersession.linkSecrets())
add(netsession.linkSecrets())
return map
end


ipnet.setKeyProvider(linkSecrets)




if link.runtime then
services[#services + 1] = {
name = substrateName,
run = link.runtime,
shutdown = link.shutdown,
running = link.isRunning,
}
end



services[#services + 1] = {
name = "ipnet",
run = ipnet.runtime,
shutdown = ipnet.shutdown,
running = ipnet.isRunning,
}

local coreServices = {






{
name = "icmp",
run = icmp.runtime,
shutdown = icmp.shutdown,
running = icmp.isRunning,
},
{
name = "acknet",
run = acknet.runtime,
shutdown = acknet.shutdown,
running = acknet.isRunning,
},
{
name = "routing",
run = routing.runtime,
shutdown = routing.shutdown,
running = routing.isRunning,
},
{
name = "netcrypt",
run = netcrypt.runtime,
shutdown = netcrypt.shutdown,
running = netcrypt.isRunning,
},
}
for _, service in ipairs(coreServices) do services[#services + 1] = service end

if isServer then
ipnet.setRoutes(ownRoutes())

routing.setLocal(ipnet.localAddress())


routing.setName(ourName())
routing.setDirectory(directoryResolver)
netsession.setAllocator(allocate)


peersession.setVoucher(ownVoucher())
peersession.setChain(netkeys.chainHex())

services[#services + 1] = {name = "handshake server", run = netsession.serve}
end

if isClient then
services[#services + 1] = {name = "client join", run = clientTask}
end




if not isServer and #declared > 0 then
bootrelay.setUpstream(routing.serverAddress)
bootrelay.setSegment(function(client)
local modem = ipnet.ingressOf(client)
for _, iface in ipairs(ipnet.interfaces()) do
if iface.modem == modem then return iface.address end
end
local first = ipnet.interfaces()[1]
return first and first.address or nil
end)

services[#services + 1] = {
name = "bootstrap relay",
run = bootrelay.runtime,
shutdown = bootrelay.shutdown,
running = bootrelay.isRunning,
}
end




services[#services + 1] = {name = "peer sessions", run = peersession.runtime}




for _, service in ipairs(services) do
if service.running and service.running() then
printError(("%s is already running"):format(service.name))
print("stop the other netstart, or run 'netstop' to clear stale flags")
return
end
end

local tasks = {}
for i, service in ipairs(services) do tasks[i] = service.run end





local ok, err = pcall(parallel.waitForAny, table.unpack(tasks))



for i = #services, 1, -1 do
local service = services[i]
if service.shutdown then
local down, reason = pcall(service.shutdown)
if not down then
printError(("%s shutdown failed: %s"):format(service.name, tostring(reason)))
end
end
end

if not ok then error(err, 0) end
]],
